// ==========================================================
// PAGE ROUTING & NAVIGATION (Exposed Early for Guaranteed Binding)
// ==========================================================
window.switchPage = function(pageId) {
  try {
    if (pageId === 'cinema') pageId = 'movies';
    if (pageId === 'livetv') pageId = 'live';
    currentActivePage = pageId;
    const targetPage = document.getElementById('page-' + pageId) || document.getElementById('view-' + pageId);
    const activeDockId = (pageId === 'collection' || pageId === 'history') ? (window.lastBrowsePage || 'home') : pageId;
    const targetTab = document.getElementById('tab-' + activeDockId);

    const prevPage = document.querySelector('.page-view.active, .t2l-view.active');
    if (prevPage && prevPage !== targetPage) {
      prevPage.classList.remove('active');
    }
    if (targetPage && !targetPage.classList.contains('active')) {
      targetPage.classList.add('active');
    }

    const prevTab = document.querySelector('.dock-tab-btn.active, .dock-item-btn.active');
    if (prevTab && prevTab !== targetTab) {
      prevTab.classList.remove('active');
      const oldPill = prevTab.querySelector('.dock-active-pill');
      if (oldPill) oldPill.remove();
    }
    if (targetTab) {
      targetTab.classList.add('active');
      if (!targetTab.querySelector('.dock-active-pill')) {
        const pill = document.createElement('span');
        pill.className = 'dock-active-pill';
        targetTab.appendChild(pill);
      }
    }

    // Toggle Header Actions:
    // On Home: 3 action buttons (Notifications, Profile, Hamburger) visible, Search hidden.
    // On Non-Home: ONLY Search button visible in that exact position. 3 action buttons hidden!
    const isHome = (pageId === 'home');
    const hdrSearch = document.getElementById('hdrSearchBtn');
    if (hdrSearch) {
      hdrSearch.style.display = isHome ? 'none' : 'flex';
    }
    document.querySelectorAll('.hdr-home-action').forEach(el => {
      el.style.display = isHome ? 'flex' : 'none';
    });

    window.scrollTo({ top: 0, behavior: 'instant' });

    // Avoid re-rendering static page views on every tab switch
    // Preserve laid out DOM tree for instant 60 FPS transition
    requestAnimationFrame(() => {
      window._renderedPages = window._renderedPages || {};
      if (pageId === 'home') {
        if (!window._renderedPages['home']) {
          window._renderedPages['home'] = true;
          renderHomePage();
        }
      } else if (pageId === 'live') {
        if (!window._renderedPages['live']) {
          window._renderedPages['live'] = true;
          renderLiveTVPage();
        }
      } else if (pageId === 'radio') {
        if (!window._renderedPages['radio']) {
          window._renderedPages['radio'] = true;
          renderRadioPage();
        }
      } else if (pageId === 'movies' || pageId === 'cinema') {
        if (!window._renderedPages['movies']) {
          window._renderedPages['movies'] = true;
          if (typeof renderMoviesPage === 'function') renderMoviesPage();
        }
      } else if (pageId === 'history') {
        if (typeof renderWatchHistoryPageUI === 'function') renderWatchHistoryPageUI();
      } else if (pageId === 'favs') {
        renderFavoritesPage();
      } else if (pageId === 'local') {
        if (!window._renderedPages['local']) {
          window._renderedPages['local'] = true;
          renderLocalPage();
          if (!window.deviceMediaScanned) {
            window.deviceMediaScanned = true;
            setTimeout(() => { autoScanDeviceMedia(); }, 150);
          }
        }
      }
    });
  } catch (e) {
    console.error('Error in switchPage(' + pageId + '):', e);
  }
};
window.navigateTo = function(viewId, btnElement) {
  window.switchPage(viewId);
};

window.toggleMenuDrawer = function() {
  try {
    const drawer = document.getElementById('sideDrawerModal') || document.getElementById('hamburgerDrawer');
    if (drawer) {
      const isCurrentlyOpen = drawer.classList.contains('is-open') || drawer.classList.contains('active');
      if (isCurrentlyOpen) {
        drawer.classList.remove('is-open');
        drawer.classList.remove('active');
        drawer.setAttribute('aria-hidden', 'true');
      } else {
        drawer.classList.add('is-open');
        drawer.classList.add('active');
        drawer.setAttribute('aria-hidden', 'false');
      }
    }
  } catch (e) {}
};
window.openHamburger = function() {
  const drawer = document.getElementById('sideDrawerModal') || document.getElementById('hamburgerDrawer');
  if (drawer) {
    drawer.classList.add('is-open');
    drawer.classList.add('active');
    drawer.setAttribute('aria-hidden', 'false');
  }
};
window.toggleSideDrawer = window.openHamburger;

window.closeHamburger = function(e) {
  try {
    if (e && e.target && e.target !== document.getElementById('hamburgerDrawer') && !e.target.closest('.t2l-icon-btn') && !e.target.classList.contains('t2l-drawer-panel')) {
      return;
    }
    const drawer = document.getElementById('sideDrawerModal') || document.getElementById('hamburgerDrawer');
    if (drawer) {
      drawer.classList.remove('is-open');
      drawer.classList.remove('active');
      drawer.setAttribute('aria-hidden', 'true');
    }
  } catch (e) {}
};

