// APPLICATION INITIALIZATION
// ==========================================================
async function initApp() {
  try { initPlayerOverlayEvents(); } catch (e) { console.warn('initPlayerOverlayEvents note:', e); }
  try { initPlayerSwipeGestures(); } catch (e) { console.warn('initPlayerSwipeGestures note:', e); }
  try { initMiniPlayerSwipe(); } catch (e) { console.warn('initMiniPlayerSwipe note:', e); }
  try { initReportModalDelegation(); } catch (e) { console.warn('initReportModalDelegation note:', e); }
  try { updateCCUI(); } catch (e) { console.warn('updateCCUI note:', e); }

  try {
    await CatalogProvider.load();
  } catch (e) {
    console.warn('CatalogProvider load note:', e);
  }

  try {
    await loadDatabase();
  } catch (e) {
    console.warn('loadDatabase dispatch note:', e);
  }

  try { loadSettingsUI(); } catch (e) {}

  try {
    if (typeof HeroCarouselController !== 'undefined' && HeroCarouselController.init) {
      HeroCarouselController.init();
    }
  } catch (e) {
    console.warn('HeroCarouselController init note:', e);
  }

  try { renderHomePage(); } catch (e) { console.error('Initial renderHomePage note:', e); }
  setTimeout(() => {
    try {
      if (typeof renderMoviesPage === 'function' && !(window._renderedPages && window._renderedPages['movies'])) {
        renderMoviesPage();
      }
    } catch (e) {}
  }, 1000);

window.dismissSplash = function dismissSplash() {
  try {
    const splash = document.getElementById('t2lSplash') || document.getElementById('t2lSplashScreen');
    if (splash && !splash.classList.contains('splash-hidden')) {
      splash.classList.add('splash-hidden');
      setTimeout(() => {
        if (splash.parentNode) splash.parentNode.removeChild(splash);
      }, 400);
    }
  } catch (e) {
    console.warn('dismissSplash error:', e);
  }
};

  // Dismiss T2L (Television to Live) Cinematic Splash Screen smoothly
  const urlParams = new URLSearchParams(window.location.search);
  const skipSplash = urlParams.get('noSplash') === '1' || (window.location.hash && window.location.hash !== '#splash');
  const splashDelay = skipSplash ? 0 : 900;
  setTimeout(() => {
    try {
      window.dismissSplash();
    } catch (e) {}
  }, splashDelay);

  // Hash deep linking for navigation & verification
  const handleHashNav = () => {
    const hash = window.location.hash ? window.location.hash.substring(1) : '';
    if (!hash) return;
    if (hash === 'cinema' || hash === 'movies') {
      switchPage('movies');
    } else if (hash === 'cinema-scroll') {
      switchPage('movies');
      document.getElementById('page-movies')?.classList.add('focus-scroll');
      document.getElementById('t2lHeader')?.classList.add('is-scrolled');
    } else if (hash === 'live') {
      switchPage('live');
    } else if (hash === 'radio') {
      switchPage('radio');
    } else if (hash === 'local' || hash === 'vault') {
      switchPage('local');
    } else if (hash === 'hamburger') {
      if (typeof openHamburger === 'function') openHamburger();
      else if (typeof toggleMenuDrawer === 'function') toggleMenuDrawer();
    } else if (hash === 'notifications') {
      if (typeof openNotificationsSheet === 'function') openNotificationsSheet();
    } else if (hash === 'profile') {
      if (typeof openProfileSheet === 'function') openProfileSheet();
    } else if (hash === 'footer') {
      switchPage('home');
      document.getElementById('page-home')?.classList.add('focus-footer');
      document.getElementById('view-home')?.classList.add('focus-footer');
    }
  };
  if (skipSplash) {
    handleHashNav();
  } else {
    setTimeout(handleHashNav, 600);
  }
  window.addEventListener('hashchange', handleHashNav);
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initApp);
} else {
  initApp();
}

const DEFAULT_REMOTE_CATALOG_URL = 'https://raw.githubusercontent.com/Abhiboss07/HindiIPTVValidator/main/data/channels.json';
window.isCatalogSyncing = false;

window.syncRemoteCatalog = async function(manualUserTrigger = false) {
  if (window.isCatalogSyncing) return;
  window.isCatalogSyncing = true;

  const statusEl = document.getElementById('catalogSyncStatusText');
  const syncBtn = document.getElementById('catalogSyncBtn');
  if (syncBtn && manualUserTrigger) {
    syncBtn.disabled = true;
    syncBtn.innerHTML = '<span>🔄</span> Syncing...';
  }
  if (statusEl) statusEl.textContent = 'Checking for updates...';

  try {
    const remoteUrl = localStorage.getItem('aakash_remote_catalog_url') || DEFAULT_REMOTE_CATALOG_URL;
    let jsonString = null;

    // Method A: Native Java HttpURLConnection Bridge (bypasses WebView CORS completely)
    if (window.AndroidMedia && window.AndroidMedia.fetchRemoteUrl) {
      jsonString = window.AndroidMedia.fetchRemoteUrl(remoteUrl);
    }

    // Method B: Web fetch fallback
    if (!jsonString) {
      try {
        const resp = await fetch(remoteUrl, { cache: 'no-store' });
        if (resp.ok) {
          jsonString = await resp.text();
        }
      } catch (eFetch) {
        console.warn('Fetch fallback error:', eFetch);
      }
    }

    if (jsonString) {
      const remoteData = JSON.parse(jsonString);
      if (Array.isArray(remoteData) && remoteData.length > 0) {
        try {
          localStorage.setItem('aakash_cached_channels', jsonString);
          localStorage.setItem('aakash_last_sync_time', new Date().toISOString());
        } catch (eStorage) {}

        channelsData = remoteData;
        console.log('🎉 Remote catalog synced successfully! Channels: ' + remoteData.length);

        if (typeof renderAllPages === 'function') {
          renderAllPages();
        }
        if (typeof renderChannelHealthManager === 'function') {
          renderChannelHealthManager();
        }

        if (statusEl) {
          statusEl.textContent = 'Last synced: Just now (' + remoteData.length + ' channels)';
        }
        if (manualUserTrigger) {
          showToast('✅ Channels updated (' + remoteData.length + ' active)');
        }
        window.isCatalogSyncing = false;
        if (syncBtn) {
          syncBtn.disabled = false;
          syncBtn.innerHTML = '<span>🔄</span> Update Now';
        }
        return true;
      }
    }
  } catch (err) {
    console.warn('syncRemoteCatalog note:', err);
  }

  window.isCatalogSyncing = false;
  if (syncBtn) {
    syncBtn.disabled = false;
    syncBtn.innerHTML = '<span>🔄</span> Update Now';
  }
  if (statusEl) {
    const lastSync = localStorage.getItem('aakash_last_sync_time');
    statusEl.textContent = lastSync ? ('Last synced: ' + new Date(lastSync).toLocaleTimeString()) : 'Channels up to date';
  }
  if (manualUserTrigger) {
    showToast('Channels are up to date');
  }
  return false;
};

async function loadDatabase() {
  // 1. Fast Cache Check: First load from localStorage cache if available for 0ms instant launch
  try {
    const cached = localStorage.getItem('aakash_cached_channels');
    if (cached) {
      const parsed = JSON.parse(cached);
      if (Array.isArray(parsed) && parsed.length > 0) {
        channelsData = parsed;
        console.log('⚡ Loaded ' + parsed.length + ' channels instantly from local storage cache');
        setTimeout(() => { syncRemoteCatalog(false); }, 1500);
        return;
      }
    }
  } catch (eCache) {
    console.warn('Cache load note:', eCache);
  }

  // 2. Bundled Asset Load: Method 1 (High speed Java AssetManager Bridge)
  if (window.AndroidMedia && window.AndroidMedia.loadAssetFile) {
    try {
      const jsonStr = window.AndroidMedia.loadAssetFile('data/channels.json');
      if (jsonStr) {
        const data = JSON.parse(jsonStr);
        if (Array.isArray(data) && data.length > 0) {
          channelsData = data;
          console.log('✅ Loaded ' + data.length + ' channels via Android AssetManager');
          setTimeout(() => { syncRemoteCatalog(false); }, 2000);
          return;
        }
      }
    } catch (e) {
      console.warn('Bridge asset load note:', e);
    }
  }

  // 3. Bundled Asset Load: Method 2 (XMLHttpRequest for file:///android_asset/ URLs)
  try {
    const xhrData = await new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open('GET', 'data/channels.json', true);
      xhr.onload = function() {
        if (xhr.status === 200 || (xhr.status === 0 && xhr.responseText)) {
          try {
            resolve(JSON.parse(xhr.responseText));
          } catch (err) {
            reject(err);
          }
        } else {
          reject(new Error('XHR status ' + xhr.status));
        }
      };
      xhr.onerror = () => reject(new Error('XHR network error'));
      xhr.send();
    });

    if (Array.isArray(xhrData) && xhrData.length > 0) {
      channelsData = xhrData;
      console.log('✅ Loaded ' + xhrData.length + ' channels via XHR');
      setTimeout(() => { syncRemoteCatalog(false); }, 2000);
      return;
    }
  } catch (eXhr) {
    console.warn('XHR load note:', eXhr);
  }

  // 4. Fallback
  channelsData = FALLBACK_CHANNELS;
  setTimeout(() => { syncRemoteCatalog(false); }, 2000);
}

function renderAllPages() {
  try { renderHomePage(); } catch (e) { console.error('renderHomePage error:', e); }
  try { renderLiveTVPage(); } catch (e) { console.error('renderLiveTVPage error:', e); }
  try { renderRadioPage(); } catch (e) { console.error('renderRadioPage error:', e); }
  try { renderLocalPage(); } catch (e) { console.error('renderLocalPage error:', e); }
  try { renderFavoritesPage(); } catch (e) { console.error('renderFavoritesPage error:', e); }
}

// ==========================================================
// 1. DYNAMIC UNIFIED HERO CAROUSEL CONTROLLER
// ==========================================================
const HeroCarouselController = {
  homeIndex: 0,
  cinemaIndex: 0,
  homeInterval: null,
  cinemaInterval: null,
  homeItems: [],
  cinemaItems: [],
  isHomePaused: false,
  isCinemaPaused: false,
  isInitialized: false,

  init() {
    this.refreshItems();
    this.startHomeRotator();
    this.startCinemaRotator();
    this.setupGestures('home', document.getElementById('homeHeroSection'));
    this.setupGestures('cinema', document.getElementById('cinemaHeroSection'));
    this.isInitialized = true;
  },

  refreshItems() {
    const all = CatalogProvider.getAll() || [];
    const preferredHomeIds = ['vod_12th_fail', 'vod_kalki_2898_ad', 'vod_jawan', 'vod_dangal', 'series_panchayat', 'vod_oppenheimer'];
    const curatedHome = preferredHomeIds.map(id => CatalogProvider.getById(id)).filter(Boolean);
    this.homeItems = curatedHome.length >= 3 ? curatedHome : all.slice(0, 6);

    const preferredCinemaIds = ['vod_kalki_2898_ad', 'vod_jawan', 'vod_12th_fail', 'vod_oppenheimer', 'vod_dangal', 'series_mirzapur'];
    const curatedCinema = preferredCinemaIds.map(id => CatalogProvider.getById(id)).filter(Boolean);
    this.cinemaItems = curatedCinema.length >= 3 ? curatedCinema : all.slice(0, 6);
  },

  renderIndicators(type) {
    const isHome = type === 'home';
    const container = document.getElementById(isHome ? 'homeHeroIndicators' : 'cinemaHeroIndicators');
    if (!container) return;
    const items = isHome ? this.homeItems : this.cinemaItems;
    const activeIdx = isHome ? this.homeIndex : this.cinemaIndex;

    container.innerHTML = items.map((_, idx) => `
      <div class="hero-indicator-dot ${idx === activeIdx ? 'active' : ''}" 
           onclick="event.stopPropagation(); HeroCarouselController.goTo('${type}', ${idx})"></div>
    `).join('');
  },

  updateHeroUI(type) {
    const isHome = type === 'home';
    const items = isHome ? this.homeItems : this.cinemaItems;
    if (!items || items.length === 0) return;
    const idx = isHome ? this.homeIndex : this.cinemaIndex;
    const item = items[idx % items.length];
    if (!item) return;

    const backdropEl = document.getElementById(isHome ? 'homeHeroBackdrop' : 'cinemaHeroBackdrop');
    const titleEl = document.getElementById(isHome ? 'homeHeroTitle' : 'cinemaHeroTitle');
    const metaEl = document.getElementById(isHome ? 'homeHeroMeta' : 'cinemaHeroMeta');
    const synopsisEl = document.getElementById(isHome ? 'homeHeroSynopsis' : 'cinemaHeroSynopsis');
    const tagEl = document.getElementById(isHome ? 'homeHeroTag' : 'cinemaHeroTag');
    const watchBtn = document.getElementById(isHome ? 'homeHeroWatchBtn' : 'cinemaHeroWatchBtn');
    const detailsBtn = document.getElementById(isHome ? 'homeHeroDetailsBtn' : 'cinemaHeroDetailsBtn');

    if (backdropEl) {
      backdropEl.style.opacity = '0.35';
      const img = new Image();
      img.onload = () => {
        backdropEl.src = item.backdropUrl || item.posterUrl || 'assets/placeholder.png';
        backdropEl.style.opacity = '1';
      };
      img.onerror = () => {
        backdropEl.src = 'assets/placeholder.png';
        backdropEl.style.opacity = '1';
      };
      img.src = item.backdropUrl || item.posterUrl || 'assets/placeholder.png';
    }

    if (titleEl) titleEl.textContent = item.title;
    if (synopsisEl) synopsisEl.textContent = item.description || '';
    if (tagEl) {
      tagEl.textContent = isHome 
        ? (item.mediaType === 'series' ? '★ Web-Series Spotlight' : '★ Premiere Spotlight') 
        : '★ Curated Cinema Showcase';
    }

    if (metaEl) {
      const q = item.qualityHonestBadge || (item.qualityClass === 'FULL HD' ? '1080p FHD' : (item.qualityClass === 'HD' ? '720p HD' : 'HD'));
      const genre = (item.genres && item.genres.length > 0) ? item.genres[0] : (item.mediaType === 'series' ? 'Web-Series' : 'Feature Film');
      metaEl.innerHTML = `
        <span>${item.year || '2024'}</span>
        <span>•</span>
        <span>${item.durationFormatted || '2h'}</span>
        <span>•</span>
        <span>${genre}</span>
        <span class="${isHome ? 'hero-quality-badge' : 'theatrical-quality-pill'}">${q}</span>
      `;
    }

    if (watchBtn) {
      watchBtn.onclick = (e) => {
        e.stopPropagation();
        startMovieStream(item.id);
      };
    }
    if (detailsBtn) {
      detailsBtn.onclick = (e) => {
        e.stopPropagation();
        openMovieDetails(item.id);
      };
    }

    this.renderIndicators(type);
  },

  startHomeRotator() {
    clearInterval(this.homeInterval);
    this.updateHeroUI('home');
    this.homeInterval = setInterval(() => {
      if (!this.isHomePaused && this.homeItems.length > 0 && !window.isPlayerActive) {
        this.homeIndex = (this.homeIndex + 1) % this.homeItems.length;
        this.updateHeroUI('home');
      }
    }, 6000);
  },

  startCinemaRotator() {
    clearInterval(this.cinemaInterval);
    this.updateHeroUI('cinema');
    this.cinemaInterval = setInterval(() => {
      if (!this.isCinemaPaused && this.cinemaItems.length > 0 && !window.isPlayerActive) {
        this.cinemaIndex = (this.cinemaIndex + 1) % this.cinemaItems.length;
        this.updateHeroUI('cinema');
      }
    }, 6500);
  },

  goTo(type, idx) {
    if (type === 'home') {
      this.homeIndex = idx;
      this.updateHeroUI('home');
    } else {
      this.cinemaIndex = idx;
      this.updateHeroUI('cinema');
    }
  },

  next(type) {
    if (type === 'home') {
      this.homeIndex = (this.homeIndex + 1) % (this.homeItems.length || 1);
      this.updateHeroUI('home');
    } else {
      this.cinemaIndex = (this.cinemaIndex + 1) % (this.cinemaItems.length || 1);
      this.updateHeroUI('cinema');
    }
  },

  prev(type) {
    if (type === 'home') {
      this.homeIndex = (this.homeIndex - 1 + this.homeItems.length) % (this.homeItems.length || 1);
      this.updateHeroUI('home');
    } else {
      this.cinemaIndex = (this.cinemaIndex - 1 + this.cinemaItems.length) % (this.cinemaItems.length || 1);
      this.updateHeroUI('cinema');
    }
  },

  setupGestures(type, el) {
    if (!el) return;
    const isHome = type === 'home';
    let startX = 0;
    let startY = 0;

    el.addEventListener('pointerenter', () => {
      if (isHome) this.isHomePaused = true;
      else this.isCinemaPaused = true;
    });

    el.addEventListener('pointerleave', () => {
      if (isHome) this.isHomePaused = false;
      else this.isCinemaPaused = false;
    });

    el.addEventListener('touchstart', (e) => {
      if (isHome) this.isHomePaused = true;
      else this.isCinemaPaused = true;
      if (e.touches && e.touches[0]) {
        startX = e.touches[0].clientX;
        startY = e.touches[0].clientY;
      }
    }, { passive: true });

    el.addEventListener('touchend', (e) => {
      if (isHome) this.isHomePaused = false;
      else this.isCinemaPaused = false;
      if (e.changedTouches && e.changedTouches[0]) {
        const diffX = e.changedTouches[0].clientX - startX;
        const diffY = e.changedTouches[0].clientY - startY;
        if (Math.abs(diffX) > 40 && Math.abs(diffX) > Math.abs(diffY)) {
          if (diffX < 0) this.next(type);
          else this.prev(type);
        }
      }
    }, { passive: true });
  }
};

window.HeroCarouselController = HeroCarouselController;

window.playCurrentHero = function(type) {
  const isHome = type === 'home';
  const items = isHome ? HeroCarouselController.homeItems : HeroCarouselController.cinemaItems;
  const idx = isHome ? HeroCarouselController.homeIndex : HeroCarouselController.cinemaIndex;
  const item = items[idx % (items.length || 1)];
  if (item) startMovieStream(item.id);
};

window.openCurrentHeroDetails = function(type) {
  const isHome = type === 'home';
  const items = isHome ? HeroCarouselController.homeItems : HeroCarouselController.cinemaItems;
  const idx = isHome ? HeroCarouselController.homeIndex : HeroCarouselController.cinemaIndex;
  const item = items[idx % (items.length || 1)];
  if (item) openMovieDetails(item.id);
};

window.openSeriesDetails = function(idOrTitle) {
  window.openMovieDetails(idOrTitle);
};

window.openPlayer = function(title, meta) {
  if (!title) return;
  // 1. Try finding in movies/series catalog
  const movie = CatalogProvider.getById(title);
  if (movie) {
    startMovieStream(movie.id);
    return;
  }
  // 2. Try finding in channels data (live TV or radio)
  const q = title.toLowerCase().trim();
  const ch = channelsData.find(c => c.name && (c.name.toLowerCase().includes(q) || q.includes(c.name.toLowerCase())));
  if (ch) {
    playChannel(ch);
    return;
  }
  // 3. Fallback: check if matches series episode pattern
  if (q.includes('panchayat')) {
    const panchayat = CatalogProvider.getById('series_panchayat');
    if (panchayat) { startMovieStream(panchayat.id); return; }
  }
  if (q.includes('mirzapur')) {
    const mirzapur = CatalogProvider.getById('series_mirzapur');
    if (mirzapur) { startMovieStream(mirzapur.id); return; }
  }
  const allMovies = CatalogProvider.getAll();
  if (allMovies && allMovies.length > 0) {
    startMovieStream(allMovies[0].id);
  }
};

let currentSpotlightFilter = 'all';

window.openSearch = function() {
  const modal = document.getElementById('spotlightSearchModal');
  if (modal) {
    modal.style.display = 'flex';
    const input = document.getElementById('spotlightInput');
    if (input) input.value = '';
    setTimeout(() => {
      if (modal.style.display !== 'none') {
        if (input) input.focus();
        renderSpotlightDefaultSuggestions();
      }
    }, 150);
  } else {
    switchPage('movies');
  }
};

window.closeSpotlightSearch = function(e) {
  if (e && e.target && e.target !== document.getElementById('spotlightSearchModal') && !e.target.closest('.spotlight-close-btn')) {
    return;
  }
  const modal = document.getElementById('spotlightSearchModal');
  if (modal) modal.style.display = 'none';
};

document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') {
    const modal = document.getElementById('spotlightSearchModal');
    if (modal && modal.style.display !== 'none') {
      window.closeSpotlightSearch();
    }
  }
});

window.setSpotlightFilter = function(filter, btnEl) {
  currentSpotlightFilter = filter;
  document.querySelectorAll('.spotlight-tag-pill').forEach(b => b.classList.remove('active'));
  if (btnEl) btnEl.classList.add('active');
  const input = document.getElementById('spotlightInput');
  const query = input ? input.value : '';
  if (query && query.trim()) {
    handleSpotlightSearch(query);
  } else {
    renderSpotlightDefaultSuggestions();
  }
};

function renderSpotlightDefaultSuggestions() {
  const container = document.getElementById('spotlightSearchResults');
  if (!container) return;

  const allMovies = typeof CatalogProvider !== 'undefined' ? CatalogProvider.getAll() : [];
  const topMovies = allMovies.slice(0, 6);
  const topChannels = (typeof channelsData !== 'undefined' ? channelsData : []).slice(0, 4);

  let html = `
    <div style="font-size: 11px; font-weight: 800; color: var(--t2l-aurora-cyan, #22D3EE); text-transform: uppercase; letter-spacing: 0.08em; margin: 4px 0 8px 2px;">
      Popular Spotlight Titles
    </div>
  `;

  topMovies.forEach(m => {
    const poster = m.posterUrl || '/assets/posters/vod_12th_fail.jpg';
    const typeLabel = m.mediaType === 'series' ? 'Series' : 'Cinema';
    const meta = `${m.year || '2024'} • ${m.primaryGenre || (m.genres ? m.genres[0] : 'Feature')} • ${m.qualityHonestBadge || m.resolution || 'HD'}`;
    html += `
      <div class="spotlight-item-card" onclick="closeSpotlightSearch(); openMovieDetails('${m.id}')">
        <img class="spotlight-item-poster" src="${poster}" alt="${m.title}" onerror="this.src='/assets/posters/vod_12th_fail.jpg'">
        <div class="spotlight-item-info">
          <div class="spotlight-item-title">${m.title}</div>
          <div class="spotlight-item-meta">${meta}</div>
        </div>
        <div class="spotlight-badge-type">${typeLabel}</div>
      </div>
    `;
  });

  if (topChannels.length > 0) {
    html += `
      <div style="font-size: 11px; font-weight: 800; color: #f43f5e; text-transform: uppercase; letter-spacing: 0.08em; margin: 12px 0 8px 2px;">
        Live Transmissions
      </div>
    `;
    topChannels.forEach(ch => {
      html += `
        <div class="spotlight-item-card" onclick="closeSpotlightSearch(); playChannelById('${ch.id}')">
          <div class="spotlight-item-icon-box">
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="7" width="20" height="15" rx="2" ry="2"></rect><polyline points="17 2 12 7 7 2"></polyline></svg>
          </div>
          <div class="spotlight-item-info">
            <div class="spotlight-item-title">${ch.name}</div>
            <div class="spotlight-item-meta">${ch.countryName || 'Global'} • ${ch.category || 'Live'}</div>
          </div>
          <div class="spotlight-badge-type" style="color: #f43f5e; background: rgba(244, 63, 94, 0.12);">LIVE</div>
        </div>
      `;
    });
  }

  container.innerHTML = html;
}

let _spotlightDebounceTimer = null;
window.handleSpotlightSearch = function(query) {
  if (_spotlightDebounceTimer) clearTimeout(_spotlightDebounceTimer);
  _spotlightDebounceTimer = setTimeout(() => {
    const container = document.getElementById('spotlightSearchResults');
    if (!container) return;

    if (!query || !query.trim()) {
      renderSpotlightDefaultSuggestions();
      return;
    }

    const q = query.toLowerCase().trim();
    let movies = typeof CatalogProvider !== 'undefined' ? CatalogProvider.search(q) : [];
    let channels = (typeof channelsData !== 'undefined' ? channelsData : []).filter(c =>
      (c.name && c.name.toLowerCase().includes(q)) ||
      (c.category && c.category.toLowerCase().includes(q)) ||
      (c.countryName && c.countryName.toLowerCase().includes(q))
    );

    if (currentSpotlightFilter === 'movies') {
      movies = movies.filter(m => m.mediaType !== 'series');
      channels = [];
    } else if (currentSpotlightFilter === 'series') {
      movies = movies.filter(m => m.mediaType === 'series');
      channels = [];
    } else if (currentSpotlightFilter === 'live') {
      movies = [];
    }

    if (movies.length === 0 && channels.length === 0) {
      container.innerHTML = `
        <div style="text-align: center; padding: 48px 16px; color: var(--t2l-text-muted, #94a3b8);">
          <div style="font-size: 32px; margin-bottom: 8px;">🔍</div>
          <div style="font-size: 15px; font-weight: 700; color: #FFFFFF; margin-bottom: 4px;">No matches found for "${query}"</div>
          <div style="font-size: 12px;">Try searching for "Kalki", "Jawan", "Discovery", or "Mirzapur"</div>
        </div>
      `;
      return;
    }

    let html = '';
    const visibleMovies = movies.slice(0, 12);
    if (visibleMovies.length > 0) {
      html += `
        <div style="font-size: 11px; font-weight: 800; color: var(--t2l-aurora-cyan, #22D3EE); text-transform: uppercase; letter-spacing: 0.08em; margin: 4px 0 8px 2px;">
          Cinema & Series Catalog (${movies.length})
        </div>
      `;
      visibleMovies.forEach(m => {
        const poster = m.posterUrl || '/assets/posters/vod_12th_fail.jpg';
        const typeLabel = m.mediaType === 'series' ? 'Series' : 'Cinema';
        const meta = `${m.year || '2024'} • ${m.primaryGenre || (m.genres ? m.genres[0] : 'Feature')} • ${m.qualityHonestBadge || m.resolution || 'HD'}`;
        html += `
          <div class="spotlight-item-card" onclick="closeSpotlightSearch(); openMovieDetails('${m.id}')">
            <img class="spotlight-item-poster" src="${poster}" alt="${m.title}" loading="lazy" decoding="async" onerror="this.src='/assets/posters/vod_12th_fail.jpg'">
            <div class="spotlight-item-info">
              <div class="spotlight-item-title">${m.title}</div>
              <div class="spotlight-item-meta">${meta}</div>
            </div>
            <div class="spotlight-badge-type">${typeLabel}</div>
          </div>
        `;
      });
    }

    const visibleChannels = channels.slice(0, 8);
    if (visibleChannels.length > 0) {
      html += `
        <div style="font-size: 11px; font-weight: 800; color: #f43f5e; text-transform: uppercase; letter-spacing: 0.08em; margin: 12px 0 8px 2px;">
          Live Channels (${channels.length})
        </div>
      `;
      visibleChannels.forEach(ch => {
        html += `
          <div class="spotlight-item-card" onclick="closeSpotlightSearch(); playChannelById('${ch.id}')">
            <div class="spotlight-item-icon-box">
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="7" width="20" height="15" rx="2" ry="2"></rect><polyline points="17 2 12 7 7 2"></polyline></svg>
            </div>
            <div class="spotlight-item-info">
              <div class="spotlight-item-title">${ch.name}</div>
              <div class="spotlight-item-meta">${ch.countryName || 'Global'} • ${ch.category || 'Live'}</div>
            </div>
            <div class="spotlight-badge-type" style="color: #f43f5e; background: rgba(244, 63, 94, 0.12);">LIVE</div>
          </div>
        `;
      });
    }

    requestAnimationFrame(() => {
      container.innerHTML = html;
    });
  }, 250);
};

window.playChannelById = function(channelId) {
  const ch = channelsData.find(c => c.id === channelId);
  if (ch) playChannel(ch);
};

function renderLiveBroadcastHomeCard(ch) {
  const viewers = ['18.4K', '14.2K', '12.8K', '9.5K', '8.1K', '6.4K'][Math.floor(Math.random() * 6)];
  return `
    <div class="theatrical-horizon-card" style="flex: 0 0 240px;" onclick="playChannelById('${ch.id}')">
      <div style="position: relative; width: 100%; height: 130px; background: var(--t2l-surface-2); display: flex; align-items: center; justify-content: center; overflow: hidden;">
        <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" style="color: var(--t2l-aurora-cyan);"><rect x="2" y="7" width="20" height="15" rx="2" ry="2"></rect><polyline points="17 2 12 7 7 2"></polyline></svg>
        <div style="position: absolute; top: 8px; left: 8px;" class="live-badge"><span class="live-badge-dot"></span> LIVE</div>
        <div style="position: absolute; top: 8px; right: 8px; background: rgba(5,6,8,0.75); padding: 2px 8px; border-radius: 9999px; font-size: 10px; font-weight: 700; color: #fff;">${viewers}</div>
      </div>
      <div class="theatrical-horizon-scrim" style="height: auto; position: relative; background: var(--t2l-surface-1); padding: 10px 12px;">
        <div class="theatrical-horizon-title" style="font-size: 13px;">${ch.name}</div>
        <div class="theatrical-horizon-meta" style="font-size: 11px;">${ch.countryName || 'Live'} • ${ch.quality || 'HD'}</div>
      </div>
    </div>
  `;
}

function renderRadioHomeCard(st) {
  return `
    <div class="radio-compact-tile" style="flex: 0 0 210px;" onclick="playChannelById('${st.id}')">
      <div class="radio-tile-art-compact">
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"></circle><polygon points="10 8 16 12 10 16 10 8"></polygon></svg>
      </div>
      <div class="radio-tile-text">
        <div class="radio-tile-name-compact" title="${st.name}">${st.name}</div>
        <div class="radio-tile-meta-compact">${st.description || st.quality || 'Live Transmission'}</div>
      </div>
    </div>
  `;
}

function renderHomePage() {
  if (HeroCarouselController && HeroCarouselController.isInitialized) {
    HeroCarouselController.refreshItems();
    HeroCarouselController.updateHeroUI('home');
  }

  // 1. Live Channels on Air Rail
  const liveNowList = document.getElementById('homeLiveNowList');
  if (liveNowList) {
    const liveStreams = channelsData.filter(c => c.type === 'tv').slice(0, 10);
    liveNowList.innerHTML = liveStreams.map(ch => renderLiveBroadcastHomeCard(ch)).join('');
  }

  // 2. Acoustic Radio Transmissions Rail
  const radioList = document.getElementById('homeRadioList');
  if (radioList) {
    const radioStreams = channelsData.filter(c => c.type === 'radio').slice(0, 8);
    radioList.innerHTML = radioStreams.map(st => renderRadioHomeCard(st)).join('');
  }

  // 3. Cinema & Web-Series Rails
  renderHomeCinemaRows();
}

async function renderHomeCinemaRows() {
  try {
    await CatalogProvider.load();
    const allMovies = CatalogProvider.getAll();
    if (!allMovies || allMovies.length === 0) return;

    // 1. Continue Watching Cinema
    const continueSection = document.getElementById('homeMovieContinueSection');
    const continueRow = document.getElementById('homeMovieContinueRow');
    if (continueSection && continueRow) {
      const historyIds = JSON.parse(localStorage.getItem('t2l_vod_history') || '[]');
      const historyMovies = historyIds.map(id => CatalogProvider.getById(id)).filter(Boolean);
      if (historyMovies.length > 0) {
        continueSection.style.display = 'block';
        continueRow.innerHTML = historyMovies.map(m => renderContinueCard(m)).join('');
      } else {
        // Show top 2 featured as starter continue bookmarks if no history yet
        const defaultContinue = [CatalogProvider.getById('series_panchayat'), CatalogProvider.getById('vod_jawan')].filter(Boolean);
        if (defaultContinue.length > 0) {
          continueSection.style.display = 'block';
          continueRow.innerHTML = defaultContinue.map(m => renderContinueCard(m)).join('');
        } else {
          continueSection.style.display = 'none';
        }
      }
    }

    // 2. Trending Bollywood Blockbusters
    const bollywoodRow = document.getElementById('homeBollywoodRow');
    if (bollywoodRow) {
      const bollywoodMovies = CatalogProvider.filterByCategory('Bollywood');
      bollywoodRow.innerHTML = (bollywoodMovies && bollywoodMovies.length > 0 ? bollywoodMovies : allMovies.slice(0, 10))
        .map(m => renderMovieCard(m)).join('');
    }

    // 3. Acclaimed Web-Series (Verified Playable Full Series)
    const webSeriesRow = document.getElementById('homeWebSeriesRow');
    if (webSeriesRow) {
      const seriesList = CatalogProvider.filterByCategory('Web-Series');
      webSeriesRow.innerHTML = (seriesList && seriesList.length > 0 ? seriesList : allMovies.filter(m => m.mediaType === 'series' && !m.isTrailerOnly && (m.streamUrl || (m.episodes && m.episodes.some(ep => ep.streamUrl)))))
        .map(m => renderMovieCard(m)).join('');
    }

    // 4. K-Drama & Asian Series (Hindi Dubbed)
    const homeAsianRow = document.getElementById('homeAsianRow');
    if (homeAsianRow) {
      const asianList = CatalogProvider.filterByCategory('Asian');
      homeAsianRow.innerHTML = (asianList && asianList.length > 0 ? asianList : allMovies.filter(m => m.region === 'ASIAN'))
        .map(m => renderMovieCard(m)).join('');
    }

    // 5. Hollywood & Global Cinema
    const hollywoodRow = document.getElementById('homeHollywoodRow');
    if (hollywoodRow) {
      const hollywoodMovies = CatalogProvider.filterByCategory('Hollywood');
      hollywoodRow.innerHTML = (hollywoodMovies && hollywoodMovies.length > 0 ? hollywoodMovies : allMovies.slice(10, 20))
        .map(m => renderMovieCard(m)).join('');
    }

    // 6. 4K Open Short Movies (Blender Foundation Showcase)
    const homeShortsRow = document.getElementById('homeShortsRow');
    if (homeShortsRow) {
      const shorts = allMovies.filter(m => m.isShortFilm || (m.categories && (m.categories.includes('short') || m.categories.includes('open_movie'))));
      homeShortsRow.innerHTML = (shorts.length > 0 ? shorts : allMovies.slice(0, 7))
        .map(m => renderMovieCard(m)).join('');
    }

    // 7. Official Trailers & Teasers Rail
    const homeTrailersRow = document.getElementById('homeTrailersRow');
    if (homeTrailersRow) {
      const trailers = CatalogProvider.filterByCategory('Trailers');
      homeTrailersRow.innerHTML = (trailers && trailers.length > 0 ? trailers : allMovies.filter(m => m.isTrailerOnly || m.sourceState === 'UPCOMING_TRAILER' || m.sourceState === 'TRAILER_ONLY'))
        .map(m => renderMovieCard(m)).join('');
    }
  } catch (e) {
    console.error('Error rendering home cinema rows:', e);
  }
}

