let currentLiveCountry = 'ALL';
let currentLiveCategory = 'ALL';
let currentLiveSearch = '';

window.getDailyHighlightedChannel = function() {
  const validChannels = channelsData.filter(c => c.type === 'tv' && c.status === 'PASS' && c.url);
  if (validChannels.length === 0) return channelsData[0];
  const now = new Date();
  const start = new Date(now.getFullYear(), 0, 0);
  const dayOfYear = Math.floor((now - start) / (1000 * 60 * 60 * 24));
  return validChannels[dayOfYear % validChannels.length];
};

window.playDailyHighlightChannel = function() {
  const ch = window.getDailyHighlightedChannel();
  if (ch) playChannel(ch);
};

window.renderLiveFlagship = function(channel) {
  if (!channel) return;
  const title = document.getElementById('liveFlagshipTitle');
  const quality = document.getElementById('liveFlagshipQuality');
  const desc = document.getElementById('liveFlagshipDesc');
  const thumbWrap = document.getElementById('liveFlagshipThumbWrap');
  const watchBtn = document.getElementById('liveFlagshipWatchBtn');

  if (title) title.textContent = channel.name;
  if (quality) quality.textContent = channel.quality || '1080p 60FPS';
  if (desc) desc.textContent = channel.description || `${channel.category || 'ENTERTAINMENT'} • ${channel.countryName || 'India'} Live Broadcast`;
  if (watchBtn) watchBtn.onclick = () => playChannel(channel);

  if (thumbWrap) {
    if (channel.thumbnail || channel.logo) {
      thumbWrap.innerHTML = `
        <img class="live-flagship-thumb" src="${channel.thumbnail || channel.logo}" alt="${channel.name}" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';">
        <div class="live-flagship-fallback-graphic" style="display: none;">
          <div class="live-broadcast-wave"></div>
          <div class="live-flagship-center">
            <span class="live-flagship-flag">${channel.flag || '📡'}</span>
            <span class="live-flagship-brand">${channel.name}</span>
          </div>
        </div>
        <div style="position: absolute; top: 12px; left: 12px;" class="live-badge"><span class="live-badge-dot"></span> LIVE ON AIR</div>
        <div style="position: absolute; top: 12px; right: 12px; background: rgba(5,6,8,0.75); padding: 4px 10px; border-radius: 9999px; font-size: 11px; font-weight: 700; color: #FFFFFF;">18.4K Watching</div>
      `;
    } else {
      thumbWrap.innerHTML = `
        <div class="live-flagship-fallback-graphic">
          <div class="live-broadcast-wave"></div>
          <div class="live-flagship-center">
            <span class="live-flagship-flag">${channel.flag || '📡'}</span>
            <span class="live-flagship-brand">${channel.name}</span>
          </div>
        </div>
        <div style="position: absolute; top: 12px; left: 12px;" class="live-badge"><span class="live-badge-dot"></span> LIVE ON AIR</div>
        <div style="position: absolute; top: 12px; right: 12px; background: rgba(5,6,8,0.75); padding: 4px 10px; border-radius: 9999px; font-size: 11px; font-weight: 700; color: #FFFFFF;">18.4K Watching</div>
      `;
    }
  }
};

function renderLiveTVPage() {
  const dailyChannel = window.getDailyHighlightedChannel();
  if (dailyChannel) window.renderLiveFlagship(dailyChannel);
  filterLiveChannels();
}

let _liveSearchDebounceTimer = null;
window.handleLiveSearch = function(val) {
  currentLiveSearch = val;
  if (_liveSearchDebounceTimer) clearTimeout(_liveSearchDebounceTimer);
  _liveSearchDebounceTimer = setTimeout(() => {
    filterLiveChannels();
  }, 120);
};

window.filterLiveCountry = function(countryCode, btnEl) {
  currentLiveCountry = countryCode.toUpperCase();
  document.querySelectorAll('#liveCountryChips .lumina-chip').forEach(b => b.classList.remove('active'));
  if (btnEl) btnEl.classList.add('active');
  filterLiveChannels();
};

window.filterLiveCategory = function(catId, btnEl) {
  currentLiveCategory = catId.toUpperCase();
  document.querySelectorAll('#liveCategoryChips .lumina-chip').forEach(b => b.classList.remove('active'));
  if (btnEl) btnEl.classList.add('active');
  filterLiveChannels();
};

function filterLiveChannels() {
  const feed = document.getElementById('liveChannelsFeed');
  if (!feed) return;
  feed.innerHTML = '';

  let list = channelsData.filter(ch => ch.type === 'tv');

  // Filter by Country
  if (currentLiveCountry !== 'ALL') {
    list = list.filter(c => c.country && c.country.toUpperCase() === currentLiveCountry);
  }

  // Filter by Category
  if (currentLiveCategory !== 'ALL') {
    if (currentLiveCategory === 'NEWS') {
      list = list.filter(c => c.category && (c.category.toLowerCase().includes('news') || c.category.toLowerCase().includes('business')));
    } else if (currentLiveCategory === 'DEVOTIONAL') {
      list = list.filter(c => c.category && (c.category.toLowerCase().includes('devotional') || c.category.toLowerCase().includes('holy') || c.category.toLowerCase().includes('spiritual') || c.category.toLowerCase().includes('religious')));
    } else if (currentLiveCategory === 'ENTERTAINMENT') {
      list = list.filter(c => c.category && (c.category.toLowerCase().includes('entertainment') || c.category.toLowerCase().includes('culture') || c.category.toLowerCase().includes('movies') || c.category.toLowerCase().includes('sports') || c.category.toLowerCase().includes('general')));
    } else if (currentLiveCategory === 'MUSIC') {
      list = list.filter(c => c.category && c.category.toLowerCase().includes('music'));
    } else if (currentLiveCategory === 'BUSINESS') {
      list = list.filter(c => c.category && c.category.toLowerCase().includes('business'));
    } else if (currentLiveCategory === 'SCIENCE') {
      list = list.filter(c => c.category && (c.category.toLowerCase().includes('science') || c.category.toLowerCase().includes('space')));
    }
  }

  // Filter by Search Query
  if (currentLiveSearch.trim() !== '') {
    const q = currentLiveSearch.toLowerCase();
    list = list.filter(c => {
      return (c.name && c.name.toLowerCase().includes(q)) ||
             (c.category && c.category.toLowerCase().includes(q)) ||
             (c.countryName && c.countryName.toLowerCase().includes(q)) ||
             (c.description && c.description.toLowerCase().includes(q));
    });
  }

  const countTitle = document.getElementById('liveChannelsCountTitle');
  if (countTitle) {
    countTitle.textContent = 'All Live Channels (' + list.length + ')';
  }

  if (list.length === 0) {
    feed.innerHTML = `
      <div style="text-align: center; padding: 40px 16px; color: #a3a3a3;">
        <div style="font-size: 32px; margin-bottom: 8px;">📡</div>
        <p style="font-size: 14px; font-weight: 600; color: #fff;">No channels matched your filter</p>
        <p style="font-size: 12px; color: #737373;">Try selecting 'All Countries' or 'All Genres'</p>
      </div>
    `;
    return;
  }

  const fragment = document.createDocumentFragment();
  const initial = list.slice(0, 24);
  initial.forEach(ch => {
    fragment.appendChild(createChannelListItem(ch));
  });
  feed.appendChild(fragment);

  if (list.length > 24) {
    let offset = 24;
    function appendRemainingLiveChannels() {
      if (offset >= list.length) return;
      const chunk = list.slice(offset, offset + 48);
      const chunkFrag = document.createDocumentFragment();
      chunk.forEach(ch => chunkFrag.appendChild(createChannelListItem(ch)));
      feed.appendChild(chunkFrag);
      offset += 48;
      if (offset < list.length) requestAnimationFrame(appendRemainingLiveChannels);
    }
    requestAnimationFrame(appendRemainingLiveChannels);
  }
}

function createChannelListItem(ch) {
  const item = document.createElement('div');
  const isFav = favorites.includes(ch.id);
  const qualityText = ch.quality || '1080p FHD';
  const countryAndCat = `${ch.countryName || 'Global'} • ${ch.category || 'Live'}`;

  item.className = 'live-channel-card channel-list-item';
  item.onclick = () => playChannel(ch);

  const fallbackSvg = `
    <div class="live-channel-icon-fallback">
      <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" style="color: var(--t2l-aurora-cyan, #22D3EE);">
        <rect x="2" y="7" width="20" height="15" rx="2" ry="2"></rect>
        <polyline points="17 2 12 7 7 2"></polyline>
      </svg>
    </div>
  `;

  const logoHtml = ch.logo
    ? `<img src="${ch.logo}" class="live-channel-logo-img" alt="${ch.name}" loading="lazy" decoding="async" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';">
       <div class="live-channel-icon-fallback" style="display: none;">
         <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" style="color: var(--t2l-aurora-cyan, #22D3EE);"><rect x="2" y="7" width="20" height="15" rx="2" ry="2"></rect><polyline points="17 2 12 7 7 2"></polyline></svg>
       </div>`
    : fallbackSvg;

  item.innerHTML = `
    <div class="live-channel-thumb-box">
      ${logoHtml}
      <div class="live-channel-badge-live">
        <span class="live-badge-dot" style="width: 5px; height: 5px;"></span>
        <span>LIVE</span>
      </div>
      <div class="live-channel-quality-badge">${qualityText}</div>
    </div>
    <div class="live-channel-info">
      <div class="live-channel-title" title="${ch.name}">${ch.name}</div>
      <div class="live-channel-meta">${countryAndCat}</div>
      <div class="live-channel-actions-row" onclick="event.stopPropagation()">
        <span style="font-size: 10.5px; color: var(--t2l-aurora-cyan, #22D3EE); font-weight: 600;">Tap to Stream</span>
        <div style="display: flex; align-items: center; gap: 2px;">
          <button class="live-channel-action-btn" onclick="copyVlcLink(event, '${ch.url}')" title="Copy VLC Link">
            <svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor"><path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z"/></svg>
          </button>
          <button class="live-channel-action-btn" onclick="toggleFav(event, '${ch.id}')" title="Bookmark">
            <svg viewBox="0 0 24 24" width="14" height="14" fill="${isFav ? '#facc15' : 'currentColor'}"><path d="M17 3H7c-1.1 0-1.99.9-1.99 2L5 21l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg>
          </button>
        </div>
      </div>
    </div>
  `;
  return item;
}

