function updateLiveNetworkSpeedDisplay() {
  const speedElem = document.getElementById('vlcLiveNetworkSpeed');
  if (!speedElem) return;
  
  let speedText = '⚡ 5G / High Speed (~65-100+ Mbps)';

  // 1. Query Android Bridge ConnectivityManager for true OS network speeds (avoids Chromium 10Mbps clamp)
  if (window.AndroidMedia && window.AndroidMedia.getNetworkSpeedInfo) {
    try {
      const net = JSON.parse(window.AndroidMedia.getNetworkSpeedInfo());
      if (net && net.connected) {
        if (net.type === 'cellular') {
          if (net.downstreamMbps >= 50 || net.downstreamKbps >= 50000) {
            speedText = `⚡ 5G Ultra High Speed (~${Math.round(net.downstreamMbps)} Mbps)`;
          } else if (net.downstreamMbps >= 10) {
            speedText = `📶 4G/5G High Speed (~${Math.round(net.downstreamMbps)} Mbps)`;
          } else {
            speedText = `📶 Mobile Data (~${net.downstreamMbps} Mbps)`;
          }
          speedElem.textContent = speedText;
          return;
        } else if (net.type === 'wifi') {
          speedText = `📶 Wi-Fi High Speed (~${Math.round(net.downstreamMbps)} Mbps)`;
          speedElem.textContent = speedText;
          return;
        } else if (net.downstreamMbps) {
          speedText = `⚡ High Speed (~${Math.round(net.downstreamMbps)} Mbps)`;
          speedElem.textContent = speedText;
          return;
        }
      }
    } catch (eNet) {}
  }

  // 2. Query Hls.js measured bandwidth estimate
  if (hlsInstance && hlsInstance.bandwidthEstimate) {
    const mbps = (hlsInstance.bandwidthEstimate / (1024 * 1024)).toFixed(1);
    if (mbps >= 15) {
      speedText = `⚡ 5G / High Speed (~${mbps} Mbps)`;
    } else {
      speedText = `Live ~ ${mbps} Mbps (Adaptive Speed)`;
    }
    speedElem.textContent = speedText;
    return;
  }

  // 3. Fallback to Navigator Connection
  const conn = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
  if (conn) {
    const downlink = conn.downlink || 10;
    const rtt = conn.rtt || 30;
    if (downlink >= 10 || rtt < 80) {
      speedText = '⚡ 5G / High Speed (~65-100+ Mbps)';
    } else {
      const effType = (conn.effectiveType || '4g').toUpperCase();
      speedText = `Live ~ ${downlink} Mbps (${effType} Active)`;
    }
  }
  speedElem.textContent = speedText;
}

window.setVlcStreamQuality = function(qualityKey, elem, explicitLevelIdx) {
  currentVlcQuality = qualityKey;
  try { localStorage.setItem('t2l_preferred_quality', qualityKey); } catch (eQ) {}

  if (explicitLevelIdx !== undefined && hlsInstance) {
    hlsInstance.currentLevel = explicitLevelIdx;
  }
  const rows = document.querySelectorAll('#vlcQualityOptionsList .vlc-radio-row');
  rows.forEach(r => r.classList.remove('active'));
  if (elem) elem.classList.add('active');

  const topLabel = document.getElementById('vlcTopQualityLabel');
  const subLabel = document.getElementById('vlcQualitySubtitle');

  const labelMap = {
    'auto': 'Auto (Adaptive Speed)',
    '4k': '4K UHD (2160p)',
    '2160p': '4K UHD (2160p)',
    '1440p': '2K QHD (1440p)',
    '2k': '2K QHD (1440p)',
    '1080p': '1080p FHD (1080p)',
    '720p': '720p HD (720p)',
    '480p': '480p SD (480p)',
    '360p': '360p Data Saver (360p)',
    '144p': '144p Ultra Low (144p)',
    'native': 'Native Master Quality'
  };

  const shortLabelMap = {
    'auto': 'AUTO',
    '4k': '4K UHD',
    '2160p': '4K UHD',
    '1440p': '2K',
    '2k': '2K',
    '1080p': '1080P',
    '720p': '720P',
    '480p': '480P',
    '360p': '360P',
    '144p': '144P',
    'native': 'NATIVE'
  };

  if (topLabel) topLabel.textContent = shortLabelMap[qualityKey] || 'AUTO';
  if (subLabel) subLabel.textContent = shortLabelMap[qualityKey] || 'Auto';

  // Apply HLS level switching
  if (hlsInstance && hlsInstance.levels && hlsInstance.levels.length > 0) {
    if (qualityKey === 'auto') {
      hlsInstance.currentLevel = -1; // Adaptive Bitrate according to network speed
    } else {
      const targetHeight = {
        '4k': 2160,
        '1080p': 1080,
        '720p': 720,
        '480p': 480,
        '360p': 360,
        '144p': 144
      }[qualityKey] || 720;

      // Find closest level by resolution
      let bestIdx = 0;
      let minDiff = Infinity;
      hlsInstance.levels.forEach((lvl, idx) => {
        const diff = Math.abs((lvl.height || 720) - targetHeight);
        if (diff < minDiff) {
          minDiff = diff;
          bestIdx = idx;
        }
      });
      hlsInstance.currentLevel = bestIdx;
    }
  } else {
    // Progressive MP4 / Direct Source
    const vid = document.getElementById('luminaVideo');
    if (vid && vid.src) {
      const curSrc = vid.src;
      let targetSrc = null;
      if (qualityKey === '360p' || qualityKey === '144p') {
        if (curSrc.includes('archive.org') && !curSrc.includes('_512kb.mp4')) {
          targetSrc = curSrc.replace(/\.mp4(\?.*)?$/i, '_512kb.mp4$1');
        }
      } else if (qualityKey === 'auto' || qualityKey === '1080p' || qualityKey === '4k' || qualityKey === '720p') {
        if (curSrc.includes('_512kb.mp4')) {
          targetSrc = curSrc.replace('_512kb.mp4', '.mp4');
        }
      }
      
      if (targetSrc && targetSrc !== curSrc) {
        const savedTime = vid.currentTime;
        const wasPlaying = !vid.paused;
        vid.src = targetSrc;
        vid.currentTime = savedTime;
        if (wasPlaying) vid.play().catch(() => {});
      }
    }
  }

  // Show central floating HUD pill
  const hud = document.getElementById('playerSwipeHud');
  const hudIcon = document.getElementById('playerSwipeHudIcon');
  const hudTitle = document.getElementById('playerSwipeHudTitle');
  const hudPct = document.getElementById('playerSwipeHudPct');
  
  if (hud && hudIcon && hudTitle && hudPct) {
    hud.className = 'player-swipe-hud-pill hud-center active';
    hudIcon.textContent = '📺';
    hudTitle.textContent = 'Stream Quality';
    hudPct.textContent = labelMap[qualityKey] || qualityKey;
    clearTimeout(hudHideTimeout);
    hudHideTimeout = setTimeout(() => {
      hud.classList.remove('active');
    }, 1400);
  }

  showToast('Quality: ' + (labelMap[qualityKey] || qualityKey));
  closeVlcQualityModal();
};

// 3. Sleep Timer
let vlcSleepTimeout = null;
let currentVlcSleepMin = 0;

window.openVlcSleepTimer = function() {
  closeVlcMoreMenu();
  const modal = document.getElementById('vlcSleepModal');
  if (modal) modal.style.display = 'flex';
};

window.closeVlcSleepModal = function() {
  const modal = document.getElementById('vlcSleepModal');
  if (modal) modal.style.display = 'none';
};

window.setVlcSleepTimer = function(mins) {
  clearTimeout(vlcSleepTimeout);
  currentVlcSleepMin = mins;
  const badge = document.getElementById('vlcSleepSubtitle');
  if (mins === 0) {
    if (badge) badge.textContent = 'Off';
    showToast('Sleep Timer Cancelled');
  } else {
    if (badge) badge.textContent = mins + 'm';
    showToast('Sleep Timer Set for ' + mins + ' min');
    vlcSleepTimeout = setTimeout(() => {
      const v = document.getElementById('luminaVideo');
      if (v) v.pause();
      minimizeToMiniPlayer(null);
      showToast('Sleep Timer: Playback Stopped');
    }, mins * 60 * 1000);
  }
  closeVlcSleepModal();
};

// 3. Playback Speed
window.openVlcSpeedModal = function() {
  closeVlcMoreMenu();
  const modal = document.getElementById('vlcSpeedModal');
  const v = document.getElementById('luminaVideo');
  const currentSpeed = v ? v.playbackRate : 1.0;
  const range = document.getElementById('vlcSpeedRange');
  const disp = document.getElementById('vlcSpeedDisplay');
  if (range) range.value = currentSpeed;
  if (disp) disp.textContent = currentSpeed.toFixed(2) + 'x';
  if (modal) modal.style.display = 'flex';
};

window.closeVlcSpeedModal = function() {
  const modal = document.getElementById('vlcSpeedModal');
  if (modal) modal.style.display = 'none';
};

window.onVlcSpeedSliderChange = function(val) {
  const speed = parseFloat(val);
  const v = document.getElementById('luminaVideo');
  if (v) v.playbackRate = speed;
  const disp = document.getElementById('vlcSpeedDisplay');
  const badge = document.getElementById('vlcSpeedSubtitle');
  if (disp) disp.textContent = speed.toFixed(2) + 'x';
  if (badge) badge.textContent = speed.toFixed(2) + 'x';
};

window.setVlcPlaybackSpeed = function(speed) {
  const v = document.getElementById('luminaVideo');
  if (v) v.playbackRate = speed;
  const range = document.getElementById('vlcSpeedRange');
  const disp = document.getElementById('vlcSpeedDisplay');
  const badge = document.getElementById('vlcSpeedSubtitle');
  if (range) range.value = speed;
  if (disp) disp.textContent = speed.toFixed(2) + 'x';
  if (badge) badge.textContent = speed.toFixed(2) + 'x';
  
  const chips = document.querySelectorAll('#vlcSpeedModal .vlc-chip-btn');
  chips.forEach(c => {
    const val = parseFloat(c.textContent);
    c.classList.toggle('active', Math.abs(val - speed) < 0.01);
  });
  showToast('Speed: ' + speed.toFixed(2) + 'x');
};

let playbackSpeeds = [1.0, 1.25, 1.5, 2.0, 0.5];
let currentSpeedIdx = 0;

window.cyclePlaybackSpeed = function() {
  currentSpeedIdx = (currentSpeedIdx + 1) % playbackSpeeds.length;
  setVlcPlaybackSpeed(playbackSpeeds[currentSpeedIdx]);
};

// 4. Jump to Time
window.openVlcJumpModal = function() {
  closeVlcMoreMenu();
  const v = document.getElementById('luminaVideo');
  const curTime = v ? Math.floor(v.currentTime) : 0;
  const m = Math.floor(curTime / 60);
  const s = Math.floor(curTime % 60);
  const minIn = document.getElementById('vlcJumpMin');
  const secIn = document.getElementById('vlcJumpSec');
  if (minIn) minIn.value = m;
  if (secIn) secIn.value = s < 10 ? '0' + s : s;
  const modal = document.getElementById('vlcJumpModal');
  if (modal) modal.style.display = 'flex';
};

window.closeVlcJumpModal = function() {
  const modal = document.getElementById('vlcJumpModal');
  if (modal) modal.style.display = 'none';
};

window.applyVlcJump = function() {
  const minIn = document.getElementById('vlcJumpMin');
  const secIn = document.getElementById('vlcJumpSec');
  const mins = parseInt(minIn ? minIn.value : 0, 10) || 0;
  const secs = parseInt(secIn ? secIn.value : 0, 10) || 0;
  const target = mins * 60 + secs;
  const v = document.getElementById('luminaVideo');
  if (v) {
    v.currentTime = target;
    showToast('Jumped to ' + formatSeekTime(target));
  }
  closeVlcJumpModal();
};

// 5. Equalizer
const VLC_EQ_PRESETS = {
  'Flat': [0, 0, 0, 0, 0],
  'Rock': [6, 3, -1, 4, 6],
  'Pop': [2, 4, 5, 2, -1],
  'Bass Boost': [8, 6, 2, 0, 0],
  'Vocals': [-2, 1, 6, 5, 1],
  'Cinema': [6, 3, 2, 3, 5]
};
const VLC_EQ_FREQS = ['60Hz', '250Hz', '1kHz', '4kHz', '14kHz'];
let currentEqPreset = 'Flat';

window.renderVlcEqualizerVisualizer = function(presetName) {
  const container = document.getElementById('vlcEqBandsContainer');
  if (!container) return;
  const targetPreset = presetName || currentEqPreset || 'Flat';
  const gains = VLC_EQ_PRESETS[targetPreset] || VLC_EQ_PRESETS['Flat'];

  let html = '';
  VLC_EQ_FREQS.forEach((freq, idx) => {
    const gain = gains[idx] || 0;
    const sign = gain > 0 ? '+' : '';
    const heightPct = Math.max(15, Math.min(100, Math.round(((gain + 12) / 24) * 85 + 15)));
    html += `
      <div class="vlc-eq-col">
        <span class="vlc-eq-db-label">${sign}${gain}dB</span>
        <div class="vlc-eq-bar-track">
          <div class="vlc-eq-bar-fill" style="height: ${heightPct}%;"></div>
        </div>
        <span class="vlc-eq-freq-label">${freq}</span>
      </div>
    `;
  });
  container.innerHTML = html;
};

