// ==========================================================
// AUDIO DSP & CLOSED CAPTIONS ENGINE
// ==========================================================
let currentTrackDelay = 0.0;
let currentAudioTrack = 'passthrough';
let webAudioCtx = null;
let webAudioSource = null;
let webAudioVocalFilter = null;
let webAudioPanner = null;

function initWebAudioDSP() {
  try {
    const videoElement = document.getElementById('luminaVideo');
    if (!videoElement) return;
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    
    if (!webAudioCtx) {
      webAudioCtx = new AudioCtx();
    }
    if (webAudioCtx.state === 'suspended') {
      webAudioCtx.resume().catch(() => {});
    }

    // Configure multi-channel downmixing for 4K SDR/HDR Dolby/DTS/Surround audio
    try {
      webAudioCtx.destination.channelCount = 2;
      webAudioCtx.destination.channelCountMode = 'explicit';
      webAudioCtx.destination.channelInterpretation = 'speakers';
    } catch (eC) {}

    // Note: Do NOT call attach WebAudio to HTML media element.
    // In Chromium/Android WebView, routing HTMLMediaElement through WebAudio silences
    // cross-origin media that lack CORS headers, causing complete audio loss.
  } catch (e) {
    console.log('Web Audio DSP initialization note:', e.message);
  }
}

