// Unified Audio Track Discovery Engine
function getAvailableAudioTracks(movie, episodeId) {
  if (typeof hlsInstance !== 'undefined' && hlsInstance && hlsInstance.audioTracks && hlsInstance.audioTracks.length > 0) {
    return {
      type: 'HLS',
      tracks: hlsInstance.audioTracks.map((t, idx) => {
        let label = t.name || t.lang || `Track ${idx + 1}`;
        const nameLower = (t.name || '').toLowerCase();
        const groupLower = (t.groupId || '').toLowerCase();
        const codecLower = (t.audioCodec || '').toLowerCase();

        let formatBadge = '';
        if (nameLower.includes('atmos') || groupLower.includes('atmos')) {
          formatBadge = 'Dolby Atmos (Spatial Audio)';
        } else if (nameLower.includes('ec-3') || groupLower.includes('ec-3') || codecLower.includes('ec-3')) {
          formatBadge = 'Dolby Digital Plus (E-AC-3 5.1)';
        } else if (nameLower.includes('ac-3') || groupLower.includes('ac-3') || codecLower.includes('ac-3')) {
          formatBadge = 'Dolby Digital (AC-3 5.1)';
        } else if (codecLower.includes('flac')) {
          formatBadge = 'FLAC Lossless Master';
        } else if (codecLower.includes('opus')) {
          formatBadge = 'Opus High Fidelity';
        } else if (codecLower.includes('mp4a.40.2') || codecLower.includes('aac')) {
          formatBadge = 'AAC-LC High Res';
        }

        return {
          index: idx,
          name: label,
          lang: t.lang || 'und',
          formatBadge: formatBadge,
          channels: t.channels || (formatBadge.includes('5.1') ? '5.1' : 'Stereo'),
          isCurrent: hlsInstance.audioTrack === idx
        };
      })
    };
  }

  let streamsMap = (movie && movie.audioStreams) || null;
  if (movie && (movie.mediaType === 'series' || movie.contentType === 'SERIES') && episodeId && movie.seasons) {
    for (const s of movie.seasons) {
      if (s.episodes) {
        const foundEp = s.episodes.find(e => String(e.id) === String(episodeId));
        if (foundEp && foundEp.audioStreams) {
          streamsMap = foundEp.audioStreams;
          break;
        }
      }
    }
  }

  if (streamsMap && Object.keys(streamsMap).length > 1) {
    const activeLang = window.selectedMovieAudioLang || (movie && movie.defaultLanguage) || Object.keys(streamsMap)[0];
    return {
      type: 'URL_SWITCH',
      tracks: Object.keys(streamsMap).map(lang => ({
        lang: lang,
        name: lang,
        url: streamsMap[lang],
        isCurrent: (lang === activeLang)
      }))
    };
  }

  // 3. Multi-Language Catalog or Container Tracks
  const multiLangs = (movie && movie.languages && movie.languages.length > 1) ? movie.languages :
                     (movie && movie.audio && movie.audio.availableLanguages && movie.audio.availableLanguages.length > 1) ? movie.audio.availableLanguages : null;

  if (multiLangs && multiLangs.length > 1) {
    const activeLang = window.selectedMovieAudioLang || (movie && movie.defaultLanguage) || multiLangs[0];
    return {
      type: 'CONTAINER_TRACKS',
      tracks: multiLangs.map((l, idx) => ({
        index: idx,
        name: l,
        lang: l,
        isCurrent: (l === activeLang)
      }))
    };
  }

  const singleLang = (movie && movie.defaultLanguage) || (movie && movie.languages && movie.languages[0]) || (movie && movie.audio && movie.audio.primaryLanguage) || 'Master Dialogue';
  return {
    type: 'SINGLE',
    tracks: [{
      index: 0,
      name: singleLang,
      lang: singleLang,
      isCurrent: true
    }]
  };
}

// 2. Dedicated Audio Track & Channels Modal (Under 3-Dots Drawer)
window.openVlcAudioModal = function(e) {
  if (e) e.stopPropagation();
  if (typeof window.closeAllVlcDialogs === 'function') window.closeAllVlcDialogs();
  const modal = document.getElementById('vlcAudioModal');
  if (!modal) return;
  modal.style.display = 'flex';

  setTimeout(() => {
    if (!modal || modal.style.display === 'none') return;
    const tracksList = document.getElementById('vlcAudioTracksList');
    if (!tracksList) return;
    let html = '';
    const movie = (typeof currentPlayingChannel !== 'undefined' && currentPlayingChannel && currentPlayingChannel.movieData) || (typeof currentSelectedMovie !== 'undefined' ? currentSelectedMovie : null);
    const audioData = getAvailableAudioTracks(movie, window.currentPlayingEpisodeId);

    if (audioData.type === 'HLS') {
      audioData.tracks.forEach(track => {
        const langName = track.name || track.lang || 'English';
        const isHi = langName.toLowerCase().includes('hindi') || track.lang === 'hi';
        const icon = isHi ? '🇮🇳' : '🌐';
        html += `
          <div class="vlc-radio-row ${track.isCurrent ? 'active' : ''}" onclick="setVlcHlsAudioTrack(${track.index}, this)">
            <span>${icon} ${escapeHtml(langName)}</span>
          </div>
        `;
      });
    } else if (audioData.type === 'URL_SWITCH') {
      audioData.tracks.forEach(track => {
        const icon = track.lang === 'Hindi' ? '🇮🇳' : (track.lang === 'English' ? '🌐' : '🎧');
        html += `
          <div class="vlc-radio-row ${track.isCurrent ? 'active' : ''}" onclick="switchMovieAudioStream('${track.lang}', this)">
            <span>${icon} ${escapeHtml(track.lang)}</span>
          </div>
        `;
      });
    } else if (audioData.type === 'CONTAINER_TRACKS') {
      audioData.tracks.forEach(track => {
        const icon = track.lang === 'Hindi' ? '🇮🇳' : (track.lang === 'English' ? '🌐' : '🎧');
        html += `
          <div class="vlc-radio-row ${track.isCurrent ? 'active' : ''}" onclick="setVlcContainerAudioTrack('${track.lang}', ${track.index}, this)">
            <span>${icon} ${escapeHtml(track.lang)}</span>
          </div>
        `;
      });
    } else {
      let primaryLang = audioData.tracks[0]?.name || (movie && movie.defaultLanguage) || 'English';
      if (primaryLang === 'Master Dialogue' || primaryLang.includes('Master')) {
        primaryLang = (movie && movie.defaultLanguage) || 'English';
      }
      const icon = (primaryLang.toLowerCase().includes('hindi')) ? '🇮🇳' : '🌐';
      html += `
        <div class="vlc-radio-row active" onclick="setVlcAudioTrack('master', this)">
          <span>${icon} ${escapeHtml(primaryLang)}</span>
        </div>
      `;
    }

    tracksList.innerHTML = html;
  }, 80);
};

window.setVlcContainerAudioTrack = function(lang, trackIdx, elem) {
  window.selectedMovieAudioLang = lang;
  localStorage.setItem('t2l_preferred_movie_audio_lang', lang);

  const rows = document.querySelectorAll('#vlcAudioTracksList .vlc-radio-row');
  rows.forEach(r => r.classList.remove('active'));
  if (elem) elem.classList.add('active');

  const subBadge = document.getElementById('vlcAudioSubtitle');
  if (subBadge) subBadge.textContent = lang;

  const videoElement = document.getElementById('luminaVideo');
  if (videoElement) {
    if (videoElement.audioTracks && videoElement.audioTracks.length > 0) {
      for (let i = 0; i < videoElement.audioTracks.length; i++) {
        videoElement.audioTracks[i].enabled = (i === trackIdx);
      }
    }
    videoElement.muted = false;
    videoElement.volume = 1.0;
  }
  if (window.AndroidMedia && typeof window.AndroidMedia.ensureAudioActive === 'function') {
    window.AndroidMedia.ensureAudioActive();
  }
  if (window.AndroidMedia && typeof window.AndroidMedia.setAudioTrack === 'function') {
    try { window.AndroidMedia.setAudioTrack(trackIdx); } catch (eTrack) {}
  }

  showToast(`Audio track set to: ${lang} 🔊`);
};

window.verifyAudioContinuity = function() {
  const video = document.getElementById('luminaVideo');
  if (video) {
    if (video.muted) {
      video.muted = false;
    }
    if (video.volume < 0.2) {
      video.volume = 1.0;
    }
  }
  if (window.AndroidMedia && typeof window.AndroidMedia.ensureAudioActive === 'function') {
    window.AndroidMedia.ensureAudioActive();
  }
};

window.switchMovieAudioStream = function(lang, elem) {
  window.selectedMovieAudioLang = lang;
  localStorage.setItem('t2l_preferred_movie_audio_lang', lang);

  const movie = (typeof currentPlayingChannel !== 'undefined' && currentPlayingChannel && currentPlayingChannel.movieData) || (typeof currentSelectedMovie !== 'undefined' ? currentSelectedMovie : null);
  if (!movie) return;

  let streamsMap = movie.audioStreams || null;
  if ((movie.mediaType === 'series' || movie.contentType === 'SERIES') && window.currentPlayingEpisodeId && movie.seasons) {
    for (const s of movie.seasons) {
      if (s.episodes) {
        const foundEp = s.episodes.find(e => String(e.id) === String(window.currentPlayingEpisodeId));
        if (foundEp && foundEp.audioStreams) {
          streamsMap = foundEp.audioStreams;
          break;
        }
      }
    }
  }

  if (streamsMap && streamsMap[lang]) {
    const newUrl = streamsMap[lang];
    const video = document.getElementById('luminaVideo');
    const savedTime = (video && !isNaN(video.currentTime)) ? video.currentTime : 0;
    const wasPaused = (video && video.paused);

    if (currentPlayingChannel) {
      currentPlayingChannel.url = newUrl;
    }
    if (activePlaybackSession) {
      activePlaybackSession.overrideUrl = newUrl;
    }

    if (video) {
      const onMetadataLoaded = function() {
        video.removeEventListener('loadedmetadata', onMetadataLoaded);
        try {
          if (savedTime > 0 && !isNaN(savedTime)) {
            video.currentTime = savedTime;
          }
        } catch (eTime) {}
        video.muted = false;
        video.volume = 1.0;
        if (!wasPaused) {
          video.play().catch(() => {});
        }
        if (window.AndroidMedia && typeof window.AndroidMedia.ensureAudioActive === 'function') {
          window.AndroidMedia.ensureAudioActive();
        }
      };
      video.addEventListener('loadedmetadata', onMetadataLoaded);
      video.src = newUrl;
      video.load();
    }

    const rows = document.querySelectorAll('#vlcAudioTracksList .vlc-radio-row');
    rows.forEach(r => r.classList.remove('active'));
    if (elem) elem.classList.add('active');

    const subBadge = document.getElementById('vlcAudioSubtitle');
    if (subBadge) subBadge.textContent = lang;

    showToast(`Switched audio track to: ${lang} 🔊`);
  }
};

window.setVlcHlsAudioTrack = function(trackIdx, elem) {
  if (typeof hlsInstance !== 'undefined' && hlsInstance && hlsInstance.audioTracks && hlsInstance.audioTracks[trackIdx]) {
    hlsInstance.audioTrack = trackIdx;
    const t = hlsInstance.audioTracks[trackIdx];
    const trackName = t.name || t.lang || `Track ${trackIdx + 1}`;
    const subBadge = document.getElementById('vlcAudioSubtitle');
    if (subBadge) subBadge.textContent = trackName;
    const rows = document.querySelectorAll('#vlcAudioTracksList .vlc-radio-row');
    rows.forEach(r => r.classList.remove('active'));
    if (elem) elem.classList.add('active');

    const video = document.getElementById('luminaVideo');
    if (video) {
      video.muted = false;
      video.volume = 1.0;
    }
    if (window.AndroidMedia && typeof window.AndroidMedia.ensureAudioActive === 'function') {
      window.AndroidMedia.ensureAudioActive();
    }
    showToast(`Switched audio track to: ${trackName} 🔊`);
  }
};

window.closeVlcAudioModal = function() {
  const modal = document.getElementById('vlcAudioModal');
  if (modal) modal.style.display = 'none';
};

// Aliases for backward compatibility
window.openVlcTracksMenu = window.openVlcSubtitlesModal;
window.closeVlcTracksModal = function() {
  window.closeVlcSubtitlesModal();
  window.closeVlcAudioModal();
};

window.setVlcAudioTrack = function(trackId, elem) {
  currentAudioTrack = trackId;
  const rows = document.querySelectorAll('#vlcAudioTracksList .vlc-radio-row');
  rows.forEach(r => r.classList.remove('active'));
  if (elem) elem.classList.add('active');

  const subBadge = document.getElementById('vlcAudioSubtitle');
  const shortNames = {
    'master': 'Studio Master',
    'hindi': 'Hindi',
    'telugu': 'Telugu',
    'tamil': 'Tamil',
    'kannada': 'Kannada',
    'malayalam': 'Malayalam',
    'marathi': 'Marathi',
    'english': 'English',
    'universal audio': 'Universal',
    'dual_left': 'Left (Hindi)',
    'dual_right': 'Right (Eng)',
    'passthrough': 'Hardware Direct'
  };
  localStorage.setItem('t2l_preferred_movie_audio_lang', shortNames[trackId] || trackId);
  if (subBadge) subBadge.textContent = shortNames[trackId] || 'Studio Master';

  const videoElement = document.getElementById('luminaVideo');
  if (videoElement) {
    videoElement.muted = false; // Ensure direct unmuted hardware sound
    videoElement.volume = 1.0;
  }

  const CANONICAL_LANG_MAP = {
    'hindi': 'hi', 'hin': 'hi', 'हिन्दी': 'hi',
    'english': 'en', 'eng': 'en',
    'japanese': 'ja', 'jpn': 'ja',
    'korean': 'ko', 'kor': 'ko',
    'telugu': 'te', 'tel': 'te',
    'tamil': 'ta', 'tam': 'ta',
    'kannada': 'kn', 'kan': 'kn',
    'malayalam': 'ml', 'mal': 'ml',
    'marathi': 'mr', 'mar': 'mr',
    'bengali': 'bn', 'ben': 'bn',
    'spanish': 'es', 'spa': 'es'
  };

  // Real HLS audio track switching via Hls.js with canonical normalization
  if (typeof hlsInstance !== 'undefined' && hlsInstance && hlsInstance.audioTracks && hlsInstance.audioTracks.length > 0) {
    const rawTarget = (shortNames[trackId] || trackId).toLowerCase();
    const targetNorm = CANONICAL_LANG_MAP[rawTarget] || rawTarget;
    const trackIndex = hlsInstance.audioTracks.findIndex(t => {
      const tLang = (t.lang || '').toLowerCase();
      const tNorm = CANONICAL_LANG_MAP[tLang] || tLang;
      const tName = (t.name || '').toLowerCase();
      return tNorm === targetNorm || tLang.includes(targetNorm) || tName.includes(targetNorm) || tName.includes(rawTarget);
    });
    if (trackIndex >= 0) {
      hlsInstance.audioTrack = trackIndex;
      console.log('Switched Hls.js audioTrack to:', trackIndex, hlsInstance.audioTracks[trackIndex]);
    }
  }

  // Apply real-time on-device processor DSP filtering
  if (webAudioCtx && webAudioVocalFilter) {
    if (trackId === 'hindi') {
      webAudioVocalFilter.gain.value = 4.5;
    } else if (trackId === 'english') {
      webAudioVocalFilter.gain.value = 3.5;
    } else {
      webAudioVocalFilter.gain.value = 0;
    }

    if (webAudioPanner) {
      if (trackId === 'dual_left') {
        webAudioPanner.pan.value = -1.0;
      } else if (trackId === 'dual_right') {
        webAudioPanner.pan.value = 1.0;
      } else {
        webAudioPanner.pan.value = 0;
      }
    }
  }

  const trackNames = {
    'master': 'Studio Master Audio Active',
    'hindi': 'Hindi (Dialogue Enhanced)',
    'english': 'English (Broadcast Stream)',
    'dual_left': 'Dual-Track Left Channel (Hindi)',
    'dual_right': 'Dual-Track Right Channel (English)',
    'passthrough': 'Dolby & Multi-Channel Hardware Passthrough'
  };

  showToast('Audio: ' + (trackNames[trackId] || 'Track Active'));
  closeVlcAudioModal();
};

let isDialogueBoostEnabled = false;
window.toggleDialogueBoost = function() {
  isDialogueBoostEnabled = !isDialogueBoostEnabled;
  const badge = document.getElementById('vlcDialogueSubtitle');
  if (webAudioVocalFilter) {
    webAudioVocalFilter.gain.value = isDialogueBoostEnabled ? 6.0 : 0.0;
  }
  if (isDialogueBoostEnabled) {
    if (badge) {
      badge.textContent = 'Active';
      badge.style.color = '#10b981';
    }
    showToast('Dialogue Clarity Boost: Active 🗣️');
  } else {
    if (badge) {
      badge.textContent = 'Off';
      badge.style.color = '';
    }
    showToast('Dialogue Clarity Boost: Off');
  }
};

let currentSubtitleTrackId = 'off';

window.adjustTrackDelay = function(offset) {
  currentTrackDelay = Math.round((currentTrackDelay + offset) * 10) / 10;
  window.currentTrackDelay = currentTrackDelay;
  const disp = document.getElementById('vlcTrackDelayText');
  const sign = currentTrackDelay > 0 ? '+' : '';
  if (disp) disp.textContent = sign + currentTrackDelay.toFixed(1) + 's';

  const videoElement = document.getElementById('luminaVideo');
  if (videoElement && videoElement.textTracks) {
    for (let i = 0; i < videoElement.textTracks.length; i++) {
      const track = videoElement.textTracks[i];
      if (track.cues) {
        for (let j = 0; j < track.cues.length; j++) {
          track.cues[j].startTime += offset;
          track.cues[j].endTime += offset;
        }
      }
    }
  }
  if (typeof currentParsedVttCues !== 'undefined' && Array.isArray(currentParsedVttCues)) {
    currentParsedVttCues.forEach(c => {
      c.start += offset;
      c.end += offset;
    });
  }
  if (typeof updateActiveCueText === 'function') {
    updateActiveCueText();
  }
  showToast('Subtitle Sync: ' + sign + currentTrackDelay.toFixed(1) + 's');
};

let aspectModes = ['fit', 'fill', 'center', 'stretch'];
let aspectLabels = ['Best Fit (16:9)', 'Fill Screen (Crop)', 'Center (100% Original)', 'Stretch to Screen'];
let currentAspectIdx = 0;

window.cycleAspectRatio = function(e) {
  if (e) e.stopPropagation();
  const videoElement = document.getElementById('luminaVideo');
  if (!videoElement) return;
  currentAspectIdx = (currentAspectIdx + 1) % aspectModes.length;
  const mode = aspectModes[currentAspectIdx];
  const label = aspectLabels[currentAspectIdx];
  videoElement.className = 'video-' + mode;
  
  // Show central floating HUD pill
  const hud = document.getElementById('playerSwipeHud');
  const hudIcon = document.getElementById('playerSwipeHudIcon');
  const hudTitle = document.getElementById('playerSwipeHudTitle');
  const hudPct = document.getElementById('playerSwipeHudPct');
  
  if (hud && hudIcon && hudTitle && hudPct) {
    hud.className = 'player-swipe-hud-pill hud-center active';
    hudIcon.textContent = '⤢';
    hudTitle.textContent = 'Aspect Ratio';
    hudPct.textContent = label;
    clearTimeout(hudHideTimeout);
    hudHideTimeout = setTimeout(() => {
      hud.classList.remove('active');
    }, 1400);
  }

  showToast('Aspect Ratio: ' + label);
  resetPlayerHideTimer();
};

window.toggleMute = function() {
  const videoElement = document.getElementById('luminaVideo');
  if (!videoElement) return;
  videoElement.muted = !videoElement.muted;
  showToast(videoElement.muted ? 'Audio Muted' : 'Audio Unmuted');
  resetPlayerHideTimer();
};

// Closed Captions Toggle
window.toggleCC = function() {
  const videoElement = document.getElementById('luminaVideo');
  const hasHlsSubs = (typeof hlsInstance !== 'undefined' && hlsInstance && hlsInstance.subtitleTracks && hlsInstance.subtitleTracks.length > 0);
  const hasNativeSubs = (videoElement && videoElement.textTracks && videoElement.textTracks.length > 0);
  
  if (!hasHlsSubs && !hasNativeSubs) {
    isCCEnabled = false;
    updateCCUI();
    showToast('No subtitles available for this stream');
    resetPlayerHideTimer();
    return;
  }
  
  if (isCCEnabled) {
    setVlcSubtitleTrack('off');
  } else {
    if (hasHlsSubs) {
      setVlcSubtitleTrack('hls:0');
    } else if (hasNativeSubs) {
      setVlcSubtitleTrack('native:0');
    }
  }
  resetPlayerHideTimer();
};

function updateCCUI() {
  const btnPlayerCC = document.getElementById('btnPlayerCC');
  const btnVlcSubtitles = document.getElementById('btnVlcSubtitles');
  const playerCcBox = document.getElementById('playerCcBox');
  const badgeText = document.getElementById('playerCcBadgeText');

  if (btnPlayerCC) {
    btnPlayerCC.classList.toggle('active', isCCEnabled);
  }
  if (btnVlcSubtitles) {
    btnVlcSubtitles.classList.toggle('active', isCCEnabled);
  }
  if (playerCcBox) {
    playerCcBox.style.display = isCCEnabled ? 'block' : 'none';
  }

  if (badgeText) {
    badgeText.textContent = isCCEnabled ? 'Subtitles [CC]' : 'Subtitles Off';
  }
}

// Auto-hide controls overlay & Double-Tap detection
let lastTapTime = 0;
let lastTapX = 0;

function initPlayerOverlayEvents() {
  const playerModal = document.getElementById('playerModal');
  const playerUiOverlay = document.getElementById('playerUiOverlay');
  const videoElement = document.getElementById('luminaVideo');
  const playerSeekFill = document.getElementById('playerSeekFill');
  const playerTimeCurrent = document.getElementById('playerTimeCurrent');
  const playerTimeTotal = document.getElementById('playerTimeTotal');

  if (playerModal) {
    playerModal.addEventListener('click', (e) => {
      if (isPlayerLocked) {
        if (!e.target.closest('#playerLockOverlay')) {
          if (typeof window.showPlayerLockPillBriefly === 'function') {
            window.showPlayerLockPillBriefly();
          }
        }
        return;
      }
      if (e.target.closest('button') || e.target.closest('.vlc-seekbar-wrap') || e.target.closest('.vlc-side-drawer') || e.target.closest('.vlc-dialog-card')) return;
      
      const now = Date.now();
      const clickX = e.clientX;
      const rect = playerModal.getBoundingClientRect();

      // Double-click/double-tap detection on left or right third of screen
      if (now - lastTapTime < 300 && Math.abs(clickX - lastTapX) < 60) {
        if (clickX < rect.width * 0.35) {
          skipTime(-10);
          lastTapTime = 0;
          return;
        } else if (clickX > rect.width * 0.65) {
          skipTime(10);
          lastTapTime = 0;
          return;
        }
      }
      lastTapTime = now;
      lastTapX = clickX;

      if (playerUiOverlay) {
        if (playerUiOverlay.classList.contains('hidden-controls')) {
          playerUiOverlay.classList.remove('hidden-controls');
          resetPlayerHideTimer();
        } else {
          playerUiOverlay.classList.add('hidden-controls');
          closeVlcMoreMenu();
        }
      }
    });
  }

  if (videoElement) {
    videoElement.addEventListener('timeupdate', () => {
      // Dynamic Subtitles & Closed Captions real-time sync
      if (isCCEnabled && typeof updateActiveCueText === 'function') {
        updateActiveCueText();
      }

      // Handle A-B Repeat Loop
      if (isVlcABRepeatActive && vlcPointA !== null && vlcPointB !== null && vlcPointB > vlcPointA) {
        if (videoElement.currentTime >= vlcPointB || videoElement.currentTime < vlcPointA) {
          videoElement.currentTime = vlcPointA;
        }
      }

      if (videoElement.duration && !isNaN(videoElement.duration)) {
        const cur = videoElement.currentTime;
        const dur = videoElement.duration;
        const pct = (cur / dur) * 100;
        if (playerSeekFill) playerSeekFill.style.width = pct + '%';
        if (playerTimeCurrent) {
          playerTimeCurrent.textContent = formatSeekTime(cur);
        }
        if (playerTimeTotal) {
          const rem = Math.max(0, dur - cur);
          playerTimeTotal.textContent = '- ' + formatSeekTime(rem);
        }
        // Save resume position for offline / local media
        if (currentPlayingChannel && currentPlayingChannel.isLocal && cur > 5) {
          try {
            localStorage.setItem('aakash_resume_' + currentPlayingChannel.id, Math.floor(cur));
          } catch (e) {}
        }
        // Save resume progress for VOD Movies & Web-Series (NEVER save for trailers)
        const activeMovie = (activePlaybackSession && CatalogProvider.getById(activePlaybackSession.contentId)) ||
                            (currentPlayingChannel && currentPlayingChannel.movieData) || null;
        const isTrailerActive = activePlaybackSession && activePlaybackSession.isTrailer;
        if (activeMovie && !isTrailerActive && cur > 3 && dur > 10) {
          try {
            const epId = (activePlaybackSession && activePlaybackSession.episodeId) || window.currentPlayingEpisodeId || null;
            const rData = {
              time: cur,
              duration: dur,
              pct: Math.min(100, Math.round(pct)),
              title: (activePlaybackSession && activePlaybackSession.overrideTitle) || activeMovie.title,
              episodeId: epId,
              updatedAt: Date.now()
            };
            localStorage.setItem('t2l_resume_' + activeMovie.id, JSON.stringify(rData));
            if (epId) {
              localStorage.setItem('t2l_resume_' + activeMovie.id + '_' + epId, JSON.stringify(rData));
            }
          } catch (e) {}

          // Check for binge-watching Next Episode banner
          if (typeof checkNextEpisodePrompt === 'function') {
            checkNextEpisodePrompt(cur, dur);
          }
        }
      } else {
        if (playerSeekFill) playerSeekFill.style.width = '100%';
        if (playerTimeCurrent) playerTimeCurrent.textContent = '0:00';
        if (playerTimeTotal) playerTimeTotal.textContent = 'LIVE';
      }
    });

    videoElement.addEventListener('play', () => {
      isPlaying = true;
      updatePlayPauseIcons(true);
      if (window.AndroidMedia && window.AndroidMedia.setPlaybackActive) {
        try { window.AndroidMedia.setPlaybackActive(true); } catch (e) {}
      }
    });
    videoElement.addEventListener('pause', () => {
      isPlaying = false;
      updatePlayPauseIcons(false);
      if (window.AndroidMedia && window.AndroidMedia.setPlaybackActive) {
        try { window.AndroidMedia.setPlaybackActive(false); } catch (e) {}
      }
    });

    videoElement.addEventListener('click', (e) => {
      // Event bubbles naturally to playerModal for overlay controls & double-tap seek
    });

    videoElement.addEventListener('ended', () => {
      if (window.AndroidMedia && window.AndroidMedia.setPlaybackActive) {
        try { window.AndroidMedia.setPlaybackActive(false); } catch (e) {}
      }
      if (currentSelectedMovie && (currentSelectedMovie.mediaType === 'series' || currentSelectedMovie.contentType === 'SERIES')) {
        playNextSeriesEpisode();
      }
    });
  }
}

let nextEpPromptShown = false;
window.checkNextEpisodePrompt = function(cur, dur) {
  if (!currentSelectedMovie || (currentSelectedMovie.mediaType !== 'series' && currentSelectedMovie.contentType !== 'SERIES')) return;
  const remaining = dur - cur;
  if (remaining <= 30 && remaining > 3 && !nextEpPromptShown && !window.nextEpDismissedForStream) {
    nextEpPromptShown = true;
    const banner = document.getElementById('playerNextEpBanner');
    if (banner) {
      banner.style.display = 'flex';
      const countdown = document.getElementById('nextEpCountdownText');
      if (countdown) countdown.textContent = 'Playing in ' + Math.ceil(remaining) + 's...';
    } else {
      showToast('Next episode starts soon ⏭️ (Tap Next to skip credits)');
    }
  }
};

window.dismissNextEpBanner = function(e) {
  if (e && e.stopPropagation) e.stopPropagation();
  window.nextEpDismissedForStream = true;
  const banner = document.getElementById('playerNextEpBanner');
  if (banner) banner.style.display = 'none';
};

window.playNextSeriesEpisode = function(e) {
  if (e && e.stopPropagation) e.stopPropagation();
  const banner = document.getElementById('playerNextEpBanner');
  if (banner) banner.style.display = 'none';
  const movie = currentSelectedMovie || (activePlaybackSession && CatalogProvider.getById(activePlaybackSession.contentId));
  if (!movie) return;

  const currentEpId = window.currentPlayingEpisodeId;
  let nextEp = null;

  if (movie.seasons && Array.isArray(movie.seasons)) {
    let foundCurrent = false;
    for (const season of movie.seasons) {
      if (!season.episodes) continue;
      for (const ep of season.episodes) {
        if (foundCurrent) {
          nextEp = ep;
          break;
        }
        if (ep.id === currentEpId) {
          foundCurrent = true;
        }
      }
      if (nextEp) break;
    }
  } else if (movie.episodes && Array.isArray(movie.episodes)) {
    const currIdx = movie.episodes.findIndex(e => e.id === currentEpId);
    if (currIdx !== -1 && currIdx + 1 < movie.episodes.length) {
      nextEp = movie.episodes[currIdx + 1];
    }
  }

  if (nextEp) {
    showToast('Playing next episode: ' + nextEp.title + ' ⏭️');
    playSeriesEpisode(movie.id, nextEp.id);
  } else {
    showToast('You have reached the latest episode! 🎬');
  }
};

// ==========================================================
// DUAL-AXIS CINEMATIC SWIPE GESTURES:
// Horizontal = Seek Forward / Backward (⏩ / ⏪)
// Left Vertical = Brightness (☀️)
// Right Vertical = Volume (🔊)
// ==========================================================
let rafSwipePending = false;
let targetSeekTime = 0;
let isSeekingGesture = false;

function formatSeekTime(secs) {
  if (isNaN(secs) || secs < 0) secs = 0;
  const m = Math.floor(secs / 60);
  const s = Math.floor(secs % 60);
  const h = Math.floor(m / 60);
  const remM = m % 60;
  if (h > 0) {
    return h + ':' + (remM < 10 ? '0' : '') + remM + ':' + (s < 10 ? '0' : '') + s;
  }
  return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
}

let initialPinchDist = 0;
let pinchTriggered = false;

function initPlayerSwipeGestures() {
  const playerModal = document.getElementById('playerModal');
  const brightOverlay = document.getElementById('playerBrightnessOverlay');
  const hud = document.getElementById('playerSwipeHud');
  const hudIcon = document.getElementById('playerSwipeHudIcon');
  const hudTitle = document.getElementById('playerSwipeHudTitle');
  const hudPct = document.getElementById('playerSwipeHudPct');

  if (!playerModal) return;

  playerModal.addEventListener('touchstart', (e) => {
    if (isPlayerLocked) {
      if (!e.target.closest('#playerLockOverlay')) {
        if (typeof window.showPlayerLockPillBriefly === 'function') {
          window.showPlayerLockPillBriefly();
        }
      }
      return;
    }
    if (e.target.closest('#vlcMoreDrawer') || e.target.closest('.vlc-side-drawer') || e.target.closest('.vlc-dialog-backdrop') || e.target.closest('.vlc-dialog-card') || e.target.closest('#vlcABRepeatBar') || e.target.closest('.vlc-drawer-scroll') || e.target.closest('#vlcMoreDrawerBackdrop') || e.target.closest('#reportChannelModal')) return;
    
    // 2-Finger Pinch Detection (VLC-style aspect zoom)
    if (e.touches.length === 2) {
      initialPinchDist = Math.hypot(e.touches[0].clientX - e.touches[1].clientX, e.touches[0].clientY - e.touches[1].clientY);
      pinchTriggered = false;
      activeGestureType = null;
      return;
    }

    if (e.touches.length !== 1) return;
    const touch = e.touches[0];
    touchStartX = touch.clientX;
    touchStartY = touch.clientY;
    touchGestureOriginY = touch.clientY;
    activeGestureType = null;
    isSeekingGesture = false;
    targetSeekTime = 0;
    initialPinchDist = 0;
  }, { passive: true });

  playerModal.addEventListener('touchmove', (e) => {
    if (isPlayerLocked) return;
    if (e.target.closest('#vlcMoreDrawer') || e.target.closest('.vlc-side-drawer') || e.target.closest('.vlc-dialog-backdrop') || e.target.closest('.vlc-dialog-card') || e.target.closest('#vlcABRepeatBar') || e.target.closest('.vlc-drawer-scroll') || e.target.closest('#vlcMoreDrawerBackdrop') || e.target.closest('#reportChannelModal')) return;

    // Handle 2-finger pinch zoom
    if (e.touches.length === 2 && initialPinchDist > 0 && !pinchTriggered) {
      const currentDist = Math.hypot(e.touches[0].clientX - e.touches[1].clientX, e.touches[0].clientY - e.touches[1].clientY);
      const pinchDiff = currentDist - initialPinchDist;
      if (Math.abs(pinchDiff) > 55) {
        pinchTriggered = true;
        cycleAspectRatio();
      }
      return;
    }

    if (e.touches.length !== 1) return;
    const touch = e.touches[0];
    const dx = touch.clientX - touchStartX;
    const dy = touchStartY - touch.clientY;
    const rect = playerModal.getBoundingClientRect();
    const videoElement = document.getElementById('luminaVideo');

    // 1. Identify gesture axis on threshold (32px deadzone protects against accidental taps and jitters)
    const minSwipeDist = 32;
    if (!activeGestureType) {
      if (Math.abs(dx) > minSwipeDist && Math.abs(dx) > Math.abs(dy) * 1.4) {
        // Horizontal Swipe -> Seeking
        activeGestureType = 'seek';
        isSeekingGesture = true;
        touchStartVal = videoElement ? videoElement.currentTime : 0;
        if (hud) hud.className = 'player-swipe-hud-pill hud-center';
      } else if (Math.abs(dy) > minSwipeDist && Math.abs(dy) > Math.abs(dx) * 1.4) {
        // Vertical Swipe: Left 42% for Brightness, Right 42% for Volume, Middle 16% is deadzone
        const relX = (touchStartX - rect.left) / (rect.width || 1);
        if (relX < 0.42) {
          activeGestureType = 'brightness';
          touchGestureOriginY = touch.clientY;
          // Synchronize with real system/hardware brightness if available
          if (window.AndroidMedia && typeof window.AndroidMedia.getBrightness === 'function') {
            try {
              const b = window.AndroidMedia.getBrightness();
              if (b > 0) currentBrightness = Math.round(b * 100);
            } catch (eB) {}
          }
          touchStartVal = currentBrightness;
          if (hud) hud.className = 'player-swipe-hud-pill hud-left';
        } else if (relX > 0.58) {
          activeGestureType = 'volume';
          touchGestureOriginY = touch.clientY;
          if (window.AndroidMedia && window.AndroidMedia.getSystemVolume) {
            touchStartVal = window.AndroidMedia.getSystemVolume();
          } else {
            touchStartVal = videoElement ? Math.round(videoElement.volume * 100) : currentVolume;
          }
          if (hud) hud.className = 'player-swipe-hud-pill hud-right';
        }
      }
    }

    if (!activeGestureType) return;
    if (e.cancelable) {
      e.preventDefault();
    }
    clearTimeout(hudHideTimeout);

    if (!rafSwipePending) {
      rafSwipePending = true;
      requestAnimationFrame(() => {
        rafSwipePending = false;
        if (!activeGestureType) return;

        // A. Horizontal Seeking
        if (activeGestureType === 'seek') {
          const duration = videoElement && videoElement.duration && !isNaN(videoElement.duration) && videoElement.duration !== Infinity 
            ? videoElement.duration 
            : 0;

          // Scale seek step based on swipe distance (up to +-120s or proportional)
          const seekRange = duration > 0 ? Math.min(300, duration * 0.4) : 90;
          const seekOffset = (dx / (rect.width * 0.7)) * seekRange;
          
          targetSeekTime = Math.max(0, touchStartVal + seekOffset);
          if (duration > 0 && targetSeekTime > duration) targetSeekTime = duration;

          const diffSecs = targetSeekTime - touchStartVal;
          const isFwd = diffSecs >= 0;

          if (hudIcon) hudIcon.textContent = isFwd ? '⏩' : '⏪';
          if (hudTitle) {
            hudTitle.textContent = (isFwd ? '+' : '') + Math.round(diffSecs) + 's (' + formatSeekTime(targetSeekTime) + ')';
          }
          if (hudPct) {
            hudPct.textContent = duration > 0 ? formatSeekTime(duration) : 'SEEK';
          }

        // B. Left Vertical Brightness (0% - 100% Hardware & Dimming, smooth zero-origin delta)
        } else if (activeGestureType === 'brightness') {
          const playerHeight = rect.height || window.innerHeight || 1;
          const currentDy = touchGestureOriginY - touch.clientY;
          const deltaPct = (currentDy / playerHeight) * 100 * 0.75;
          currentBrightness = Math.max(5, Math.min(100, Math.round(touchStartVal + deltaPct)));
          
          // 1. Android Native Hardware Screen Brightness
          if (window.AndroidMedia && window.AndroidMedia.setBrightness) {
            window.AndroidMedia.setBrightness(Math.max(0.01, currentBrightness / 100));
          }

          // 2. Pure Black Dimming Overlay (Never white boost!)
          if (brightOverlay) {
            brightOverlay.style.background = '#000000';
            const dimOpacity = Math.max(0, (100 - currentBrightness) / 100 * 0.85);
            brightOverlay.style.opacity = dimOpacity.toFixed(2);
          }
          if (hudIcon) hudIcon.textContent = '☀️';
          if (hudTitle) hudTitle.textContent = 'Brightness';
          if (hudPct) hudPct.textContent = currentBrightness + '%';

        // C. Right Vertical Volume
        } else if (activeGestureType === 'volume') {
          const playerHeight = rect.height || window.innerHeight || 1;
          const currentDy = touchGestureOriginY - touch.clientY;
          const deltaPct = (currentDy / playerHeight) * 100 * 0.75;
          currentVolume = Math.max(0, Math.min(100, Math.round(touchStartVal + deltaPct)));
          
          if (window.AndroidMedia && window.AndroidMedia.setSystemVolume) {
            window.AndroidMedia.setSystemVolume(currentVolume);
          }
          if (videoElement) {
            videoElement.volume = currentVolume / 100;
            if (!isNativeDDPActive && videoElement.muted && currentVolume > 0) videoElement.muted = false;
          }
          if (isNativeDDPActive && window.AndroidMedia && window.AndroidMedia.syncNativeAudio) {
            window.AndroidMedia.syncNativeAudio(videoElement.currentTime, !videoElement.paused, currentVolume / 100);
          }
          if (hudIcon) hudIcon.textContent = currentVolume === 0 ? '🔇' : (currentVolume > 50 ? '🔊' : '🔉');
          if (hudTitle) hudTitle.textContent = 'Volume';
          if (hudPct) hudPct.textContent = currentVolume + '%';
        }

        if (hud) hud.classList.add('active');
      });
    }
  }, { passive: false });

  playerModal.addEventListener('touchend', () => {
    initialPinchDist = 0;
    pinchTriggered = false;

    if (!activeGestureType) return;
    
    // If seek gesture finished, apply the target seek position
    if (activeGestureType === 'seek') {
      const videoElement = document.getElementById('luminaVideo');
      if (videoElement && targetSeekTime >= 0) {
        try {
          videoElement.currentTime = targetSeekTime;
        } catch (e) {}
      }
    }

    activeGestureType = null;
    isSeekingGesture = false;
    hudHideTimeout = setTimeout(() => {
      if (hud) hud.classList.remove('active');
    }, 1100);
  }, { passive: true });
}

