const CatalogProvider = {
  movies: (function() {
    if (typeof DEFAULT_MOVIES_CATALOG === 'undefined' || !DEFAULT_MOVIES_CATALOG) return [];
    if (Array.isArray(DEFAULT_MOVIES_CATALOG)) return DEFAULT_MOVIES_CATALOG;
    if (Array.isArray(DEFAULT_MOVIES_CATALOG.movies)) return DEFAULT_MOVIES_CATALOG.movies;
    return [];
  })(),
  loaded: false,
  async load() {
    const CURRENT_CATALOG_VERSION = 19;
    try {
      const storedVer = localStorage.getItem('t2l_catalog_version');
      if (storedVer !== String(CURRENT_CATALOG_VERSION)) {
        localStorage.removeItem('t2l_movies_catalog_cache');
        localStorage.setItem('t2l_catalog_version', String(CURRENT_CATALOG_VERSION));
      }
    } catch (eVer) {}

    if (this.loaded && this.movies.length > 52) return this.movies;
    let rawList = null;

    // 1. Android AssetManager / Native Catalog Bridge
    if (window.AndroidMedia) {
      try {
        let assetStr = null;
        if (typeof window.AndroidMedia.getMoviesCatalogJson === 'function') {
          assetStr = window.AndroidMedia.getMoviesCatalogJson();
        } else if (typeof window.AndroidMedia.loadAssetFile === 'function') {
          assetStr = window.AndroidMedia.loadAssetFile('data/movies_catalog.json');
        }
        if (assetStr) {
          const parsed = JSON.parse(assetStr);
          rawList = Array.isArray(parsed) ? parsed : (parsed.movies || []);
          console.log('✅ Loaded ' + rawList.length + ' titles from Android Native Bridge');
        }
      } catch (eAsset) {
        console.warn('Bridge movies load note:', eAsset);
      }
    }

    // 2. XMLHttpRequest for file:///android_asset/ URLs
    if (!rawList || rawList.length === 0) {
      try {
        const parsed = await new Promise((resolve, reject) => {
          const xhr = new XMLHttpRequest();
          xhr.open('GET', 'data/movies_catalog.json', true);
          xhr.onload = function() {
            if (xhr.status === 200 || (xhr.status === 0 && xhr.responseText)) {
              try { resolve(JSON.parse(xhr.responseText)); } catch (err) { reject(err); }
            } else {
              reject(new Error('XHR status ' + xhr.status));
            }
          };
          xhr.onerror = () => reject(new Error('XHR error'));
          xhr.send();
        });
        rawList = Array.isArray(parsed) ? parsed : (parsed.movies || []);
      } catch (eXhr) {
        console.warn('XHR movies load note:', eXhr);
      }
    }

    // 3. fetch fallback
    if (!rawList || rawList.length === 0) {
      try {
        const res = await fetch('data/movies_catalog.json');
        if (res.ok) {
          const parsed = await res.json();
          rawList = Array.isArray(parsed) ? parsed : (parsed.movies || []);
        }
      } catch (eFetch) {
        console.warn('Fetch movies fallback:', eFetch);
      }
    }

    if (rawList && rawList.length > 0) {
      this.movies = rawList.map(m => {
        if (!m.posterUrl && m.poster) m.posterUrl = m.poster;
        if (!m.backdropUrl) m.backdropUrl = m.posterUrl;
        if (!m.durationFormatted && m.runtime) m.durationFormatted = m.runtime;
        if (!m.duration && m.duration_seconds) m.duration = m.duration_seconds;
        if (!m.rating && m.imdb_rating) m.rating = parseFloat(m.imdb_rating);
        if (!m.genres && m.genre) m.genres = m.genre.split('/').map(s => s.trim());
        if (!m.fileSize && m.size) m.fileSize = m.size;
        if (!m.torrentUri && m.sources && m.sources.magnet) m.torrentUri = m.sources.magnet;
        if (!m.streamUrl && m.sources && m.sources.direct_fallback) m.streamUrl = m.sources.direct_fallback;
        if (!m.type) {
          if (m.categories && m.categories.includes('hollywood')) m.type = 'Hollywood';
          else if (m.categories && m.categories.includes('bollywood')) m.type = 'Bollywood';
          else if (m.categories && m.categories.includes('thrillers')) m.type = 'Thrillers';
          else if (m.categories && m.categories.includes('action')) m.type = 'Action';
          else m.type = 'Open Movies';
        }
        return m;
      });
      this.loaded = true;
      this._buildIndices();
      return this.movies;
    }

    this.movies = DEFAULT_MOVIES_CATALOG;
    this.loaded = true;
    this._buildIndices();
    return this.movies;
  },
  _byIdMap: null,
  _searchIndex: null,
  _buildIndices() {
    this._byIdMap = new Map();
    this._searchIndex = [];
    const items = this.getAll();
    for (let i = 0; i < items.length; i++) {
      const m = items[i];
      if (m && m.id) {
        this._byIdMap.set(m.id, m);
      }
      const langStr = Array.isArray(m.languages) ? m.languages.join(' ') : '';
      const genreStr = Array.isArray(m.genres) ? m.genres.join(' ') : '';
      const catStr = Array.isArray(m.categories) ? m.categories.join(' ') : '';
      const tokens = [
        m.title || '',
        m.description || '',
        m.cast || '',
        m.director || '',
        m.year ? String(m.year) : '',
        m.type || '',
        m.region || '',
        m.mediaType || '',
        langStr,
        genreStr,
        catStr
      ].join(' ').toLowerCase();
      this._searchIndex.push({ item: m, text: tokens });
    }
  },
  getAll() {
    if (this.movies && Array.isArray(this.movies) && this.movies.length > 0) return this.movies;
    if (typeof DEFAULT_MOVIES_CATALOG !== 'undefined' && DEFAULT_MOVIES_CATALOG) {
      if (Array.isArray(DEFAULT_MOVIES_CATALOG)) return DEFAULT_MOVIES_CATALOG;
      if (Array.isArray(DEFAULT_MOVIES_CATALOG.movies)) return DEFAULT_MOVIES_CATALOG.movies;
    }
    return [];
  },
  getById(id) {
    if (!id) return null;
    if (typeof id === 'object' && id.id) return id;
    if (!this._byIdMap) this._buildIndices();
    let found = this._byIdMap ? this._byIdMap.get(id) : null;
    if (found) return found;
    const all = this.getAll();
    found = all.find(m => m.id === id);
    if (found) return found;
    const idStr = String(id).toLowerCase().trim();
    return all.find(m => m.title && m.title.toLowerCase().trim() === idStr) ||
           all.find(m => m.title && (m.title.toLowerCase().includes(idStr) || idStr.includes(m.title.toLowerCase()))) || null;
  },
  filterByCategory(cat) {
    const list = this.getAll();
    if (!cat || cat === 'all' || cat === 'HindiFirst') return list;
    if (cat === 'Web-Series') return list.filter(m => (m.mediaType === 'series' || (m.categories && (m.categories.includes('web_series') || m.categories.includes('web-series')))) && !m.isTrailerOnly && m.sourceState !== 'UPCOMING_TRAILER' && m.sourceState !== 'TRAILER_ONLY' && (m.streamUrl || (m.episodes && m.episodes.some(ep => ep.streamUrl)))).sort((a, b) => (b.featured ? 1 : 0) - (a.featured ? 1 : 0) || (b.rating || 0) - (a.rating || 0));
    if (cat === 'Movies') return list.filter(m => m.mediaType !== 'series' && !m.isTrailerOnly && m.sourceState !== 'UPCOMING_TRAILER' && m.sourceState !== 'TRAILER_ONLY');
    if (cat === 'K-Drama') return list.filter(m => m.type === 'K-Drama' || (m.categories && m.categories.includes('korean')));
    if (cat === 'C-Drama') return list.filter(m => m.type === 'C-Drama' || (m.categories && m.categories.includes('chinese')));
    if (cat === 'Anime') return list.filter(m => m.type === 'Anime' || (m.categories && m.categories.includes('anime')));
    if (cat === 'Asian') return list.filter(m => m.region === 'ASIAN' || m.type === 'Asian Cinema' || (m.categories && (m.categories.includes('asian') || m.categories.includes('korean') || m.categories.includes('chinese'))));
    if (cat === 'Hindi') return list.filter(m => (m.languages && m.languages.some(l => l.toLowerCase().includes('hindi'))) || m.type === 'Bollywood' || m.region === 'BOLLYWOOD');
    if (cat === 'English') return list.filter(m => (m.languages && m.languages.some(l => l.toLowerCase().includes('english'))));
    if (cat === 'Bollywood') return list.filter(m => (m.region === 'BOLLYWOOD' || m.type === 'Bollywood' || (m.categories && m.categories.includes('bollywood'))) && m.mediaType !== 'series' && !m.isTrailerOnly && m.sourceState !== 'UPCOMING_TRAILER' && m.sourceState !== 'TRAILER_ONLY' && m.contentType !== 'TRAILER').sort((a, b) => (b.featured ? 1 : 0) - (a.featured ? 1 : 0) || (b.rating || 0) - (a.rating || 0));
    if (cat === 'Hollywood') return list.filter(m => (m.region === 'HOLLYWOOD' || m.type === 'Hollywood' || (m.categories && m.categories.includes('hollywood'))) && m.mediaType !== 'series' && !m.isTrailerOnly && m.sourceState !== 'UPCOMING_TRAILER' && m.sourceState !== 'TRAILER_ONLY' && m.contentType !== 'TRAILER');
    if (cat === 'Trailers') return list.filter(m => m.isTrailerOnly || m.sourceState === 'TRAILER_ONLY' || m.sourceState === 'UPCOMING_TRAILER' || m.contentType === 'TRAILER' || (m.categories && m.categories.includes('trailers')) || (!m.streamUrl && (!m.episodes || !m.episodes.some(ep => ep.streamUrl)) && m.trailerUrl));
    if (cat === 'Featured') return list.filter(m => m.featured);
    const catLower = cat.toLowerCase();
    return list.filter(m => {
      if (m.region && m.region.toLowerCase() === catLower) return true;
      if (m.type && m.type.toLowerCase() === catLower) return true;
      if (m.categories && m.categories.some(c => c.toLowerCase() === catLower)) return true;
      if (m.genres && m.genres.some(g => g.toLowerCase().includes(catLower))) return true;
      return false;
    });
  },
  search(query) {
    const list = this.getAll();
    if (!query) return list;
    const q = query.toLowerCase().trim();
    if (!this._searchIndex || this._searchIndex.length !== list.length) {
      this._buildIndices();
    }
    const terms = q.split(/\s+/).filter(Boolean);
    if (terms.length === 0) return list;
    return this._searchIndex.filter(entry => {
      const text = entry.text;
      for (let t = 0; t < terms.length; t++) {
        const term = terms[t];
        if (term === 'series') {
          if (entry.item.mediaType === 'series') continue;
        } else if (term === 'movie') {
          if (entry.item.mediaType !== 'series') continue;
        }
        if (!text.includes(term)) return false;
      }
      return true;
    }).map(entry => entry.item);
  }
};

let currentSelectedMovie = null;
let streamPrepInterval = null;
let downloadsManagerInterval = null;
let activeDownloadsTab = 'active';

function getSwarmBadgeMarkup(seeders) {
  const count = seeders || 40;
  if (count >= 80) {
    return `<div class="movie-swarm-badge swarm-excellent"><span class="swarm-dot" style="color:#22c55e;">●</span> High Health (${count}+)</div>`;
  } else if (count >= 40) {
    return `<div class="movie-swarm-badge swarm-good"><span class="swarm-dot" style="color:#eab308;">●</span> Moderate (${count}+)</div>`;
  } else {
    return `<div class="movie-swarm-badge swarm-poor"><span class="swarm-dot" style="color:#ef4444;">●</span> Low Swarm (${count})</div>`;
  }
}

function renderContinueCard(movie, pct) {
  let progressPct = pct;
  if (!progressPct) {
    try {
      const resumeRaw = localStorage.getItem('t2l_resume_' + movie.id);
      if (resumeRaw) {
        const r = JSON.parse(resumeRaw);
        if (r && r.pct) progressPct = Math.round(r.pct);
      }
    } catch (e) {}
  }
  if (!progressPct || progressPct < 5) progressPct = 42;
  if (progressPct > 95) progressPct = 90;

  const thumb = movie.backdropUrl || movie.posterUrl || 'assets/placeholder.png';
  return `
    <div class="continue-card" onclick="openMovieDetails('${movie.id}')" title="${movie.title}">
      <div class="continue-backdrop-wrap">
        <img class="continue-backdrop-img" 
             src="${thumb}" 
             alt="${movie.title}" 
             loading="lazy"
             onerror="this.onerror=null; this.src='assets/placeholder.png';" />
        <div class="continue-play-glyph">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg>
        </div>
        <div class="continue-progress-bar">
          <div class="continue-progress-fill" style="width: ${progressPct}%;"></div>
        </div>
      </div>
      <div class="continue-info">
        <div class="continue-title">${movie.title}</div>
        <div class="continue-subtext">${movie.mediaType === 'series' ? 'Resume Episode' : 'Resume Playback'} • ${progressPct}%</div>
      </div>
    </div>
  `;
}

function renderScopeCard(movie) {
  const thumb = movie.backdropUrl || movie.posterUrl || 'assets/placeholder.png';
  const isSeries = movie.mediaType === 'series';
  const durationOrType = isSeries ? 'Series' : (movie.durationFormatted || (movie.genres && movie.genres[0]) || 'Theatrical');
  return `
    <div class="theatrical-horizon-card" onclick="openMovieDetails('${movie.id}')" title="${movie.title}">
      <img class="theatrical-horizon-thumb" 
           src="${thumb}" 
           alt="${movie.title}" 
           loading="lazy"
           onerror="this.onerror=null; this.src='assets/placeholder.png';" />
      <div class="theatrical-horizon-scrim">
        <div class="theatrical-horizon-title">${movie.title}</div>
        <div class="theatrical-horizon-meta">
          <span>${movie.year || '2024'}</span>
          <span>•</span>
          <span>${durationOrType}</span>
          <span>•</span>
          <span class="theatrical-quality-pill">2.39:1 SCOPE</span>
        </div>
      </div>
    </div>
  `;
}

function renderMovieCard(movie) {
  const poster = movie.posterUrl || 'assets/placeholder.png';
  const isSeries = movie.mediaType === 'series';
  const sState = movie.sourceState || (movie.streamUrl ? 'DIRECT_STREAM_AVAILABLE' : (movie.trailerUrl ? 'TRAILER_ONLY' : (movie.torrentUri ? 'TORRENT_SOURCE_AVAILABLE' : 'NO_AUTHORIZED_SOURCE')));

  let qualityText = 'HD';
  const qb = (movie.qualityHonestBadge || '').toLowerCase();
  const qc = (movie.qualityClass || '').toUpperCase();
  const res = (movie.resolution || '').toLowerCase();
  const sUrl = (movie.streamUrl || '').toLowerCase();

  if (movie.isTrailerOnly || sState === 'TRAILER_ONLY' || sState === 'UPCOMING_TRAILER' || (!movie.streamUrl && !movie.torrentUri && movie.trailerUrl)) {
    qualityText = 'Official Trailer';
  } else if (movie.isShortFilm || (movie.categories && movie.categories.includes('short'))) {
    qualityText = (qb.includes('4k') || qc === '4K') ? '4K Short' : 'Short Film';
  } else if (qb.includes('4k') || qb.includes('2160') || qc === '4K' || qc === 'UHD' || res.includes('2160') || res.includes('4k') || sUrl.includes('2160p')) {
    qualityText = '4K UHD';
  } else if (qb.includes('1080') || qc === 'FULL HD' || qc.includes('1080') || res.includes('1080') || res.includes('fhd') || sUrl.includes('1080p') || sUrl.includes('bluray')) {
    qualityText = '1080p';
  } else if (qb.includes('720') || qc === 'HD' || qc.includes('720') || res.includes('720') || sUrl.includes('720p')) {
    qualityText = '720p HD';
  } else if (movie.trailerUrl && !movie.streamUrl) {
    qualityText = 'Official Trailer';
  }

  const durationOrType = isSeries ? 'Series' : (movie.isShortFilm ? 'Short Film' : (movie.isTrailerOnly || sState === 'TRAILER_ONLY' || sState === 'UPCOMING_TRAILER' ? 'Trailer' : (movie.durationFormatted || (movie.genres && movie.genres[0]) || 'Feature')));

  return `
    <div class="theatrical-card" onclick="openMovieDetails('${movie.id}')" title="${movie.title}">
      <div class="theatrical-poster-wrap">
        <img class="theatrical-poster-img" 
             src="${poster}" 
             alt="${movie.title}" 
             loading="lazy"
             onerror="this.onerror=null; this.src='assets/placeholder.png';" />
      </div>
      <div class="theatrical-info">
        <div class="theatrical-title">${movie.title}</div>
        <div class="theatrical-meta">
          <span>${movie.year || '2024'} • ${durationOrType}</span>
          <span class="theatrical-quality-pill">${qualityText}</span>
        </div>
      </div>
    </div>
  `;
}

window.renderMoviesPage = async function() {
  await CatalogProvider.load();
  const allMovies = CatalogProvider.getAll();
  if (!allMovies || allMovies.length === 0) return;

  // Mark rendered page immediately to avoid duplicate runs
  window._renderedPages = window._renderedPages || {};
  window._renderedPages['movies'] = true;

  // 1. Frame 0: Update Hero and Above-The-Fold Visible Rails (Rails 1 & 2)
  if (typeof HeroCarouselController !== 'undefined') {
    HeroCarouselController.refreshItems();
    HeroCarouselController.updateHeroUI('cinema');
  }

  const rowsContainer = document.getElementById('moviesRowsContainer');
  const heroSection = document.getElementById('cinemaHeroSection') || document.getElementById('moviesHeroSection');
  const gridSection = document.getElementById('moviesGridSection');

  if (rowsContainer) rowsContainer.style.display = 'block';
  if (heroSection) heroSection.style.display = 'flex';
  if (gridSection) gridSection.style.display = 'none';

  // Rail 1: Trending in Theatres (Horizontal Scope 2.39:1)
  const scopeRow = document.getElementById('moviesScopeRow');
  if (scopeRow) {
    const scopeMovies = allMovies.filter(m => m.featured || m.rating >= 8.0 || (m.categories && m.categories.includes('theatrical'))).slice(0, 8);
    scopeRow.innerHTML = (scopeMovies.length > 0 ? scopeMovies : allMovies.slice(0, 8)).map(m => renderScopeCard(m)).join('');
  }

  // Rail 2: Bollywood Blockbusters
  const bollywoodRow = document.getElementById('moviesBollywoodRow');
  if (bollywoodRow) {
    const list = allMovies.filter(m => (m.type === 'Bollywood' || (m.categories && m.categories.includes('bollywood')) || (m.languages && m.languages.includes('Hindi'))) && m.mediaType !== 'series' && !m.isTrailerOnly && m.sourceState !== 'UPCOMING_TRAILER' && m.sourceState !== 'TRAILER_ONLY' && m.contentType !== 'TRAILER').sort((a, b) => (b.featured ? 1 : 0) - (a.featured ? 1 : 0) || (b.rating || 0) - (a.rating || 0));
    bollywoodRow.innerHTML = (list.length > 0 ? list : allMovies.slice(0, 10)).map(m => renderMovieCard(m)).join('');
  }

  // Frame 1 (rAF): Rails 3, 4, 5
  requestAnimationFrame(() => {
    // Rail 3: Multi-Season Epics & Sagas
    const webSeriesRow = document.getElementById('moviesWebSeriesRow');
    if (webSeriesRow) {
      const list = allMovies.filter(m => (m.mediaType === 'series' || (m.categories && (m.categories.includes('web_series') || m.categories.includes('web-series')))) && !m.isTrailerOnly && m.sourceState !== 'UPCOMING_TRAILER' && m.sourceState !== 'TRAILER_ONLY' && (m.streamUrl || (m.episodes && m.episodes.some(ep => ep.streamUrl)))).sort((a, b) => (b.featured ? 1 : 0) - (a.featured ? 1 : 0) || (b.rating || 0) - (a.rating || 0));
      webSeriesRow.innerHTML = (list.length > 0 ? list : allMovies.filter(m => m.mediaType === 'series' && !m.isTrailerOnly && (m.streamUrl || (m.episodes && m.episodes.some(ep => ep.streamUrl))))).map(m => renderMovieCard(m)).join('');
    }

    // Rail 4: K-Drama & Asian Sagas
    const asianRow = document.getElementById('moviesAsianRow');
    if (asianRow) {
      const list = allMovies.filter(m => m.region === 'ASIAN' || m.type === 'K-Drama' || m.type === 'C-Drama' || (m.categories && (m.categories.includes('korean') || m.categories.includes('chinese') || m.categories.includes('asian'))));
      asianRow.innerHTML = (list.length > 0 ? list : allMovies.filter(m => m.region === 'ASIAN')).map(m => renderMovieCard(m)).join('');
    }

    // Rail 5: Hollywood & Worldwide Hits
    const hollywoodRow = document.getElementById('moviesHollywoodRow');
    if (hollywoodRow) {
      const list = allMovies.filter(m => (m.type === 'Hollywood' || (m.categories && m.categories.includes('hollywood'))) && m.mediaType !== 'series' && !m.isTrailerOnly && m.sourceState !== 'UPCOMING_TRAILER' && m.sourceState !== 'TRAILER_ONLY' && m.contentType !== 'TRAILER');
      hollywoodRow.innerHTML = (list.length > 0 ? list : allMovies.slice(10, 20)).map(m => renderMovieCard(m)).join('');
    }

    // Frame 2 (rAF): Rails 6, 7, 8
    requestAnimationFrame(() => {
      // Rail 6: Anime & Animation
      const animeRow = document.getElementById('moviesAnimeRow');
      if (animeRow) {
        const list = allMovies.filter(m => m.type === 'Anime' || (m.categories && m.categories.includes('anime')));
        animeRow.innerHTML = (list.length > 0 ? list : allMovies.filter(m => m.genres && m.genres.includes('Animation'))).map(m => renderMovieCard(m)).join('');
      }

      // Rail 7: High-Stakes Thrillers & Mystery
      const thrillersRow = document.getElementById('moviesThrillersRow');
      if (thrillersRow) {
        const list = allMovies.filter(m => m.type === 'Thrillers' || (m.categories && m.categories.includes('thrillers')) || (m.genres && m.genres.some(g => g.toLowerCase().includes('thriller'))));
        thrillersRow.innerHTML = (list.length > 0 ? list : allMovies.slice(5, 15)).map(m => renderMovieCard(m)).join('');
      }

      // Rail 8: High-Octane Action
      const actionRow = document.getElementById('moviesActionRow');
      if (actionRow) {
        const list = allMovies.filter(m => m.type === 'Action' || (m.categories && m.categories.includes('action')) || (m.genres && m.genres.some(g => g.toLowerCase().includes('action'))));
        actionRow.innerHTML = (list.length > 0 ? list : allMovies.slice(8, 18)).map(m => renderMovieCard(m)).join('');
      }

      // Frame 3 (rAF): Rails 9, 10, 11
      requestAnimationFrame(() => {
        // Rail 9: Public Domain & Heritage Classics
        const classicsRow = document.getElementById('moviesClassicsRow');
        if (classicsRow) {
          const list = allMovies.filter(m => (m.region === 'PUBLIC_DOMAIN' || (m.categories && m.categories.includes('classics')) || (m.year && parseInt(m.year, 10) < 2010)) && !m.isShortFilm);
          classicsRow.innerHTML = (list.length > 0 ? list : allMovies.slice(0, 8)).map(m => renderMovieCard(m)).join('');
        }

        // Rail 10: 4K Open Short Movies
        const shortsRow = document.getElementById('moviesShortsRow');
        if (shortsRow) {
          const list = allMovies.filter(m => m.isShortFilm || (m.categories && (m.categories.includes('short') || m.categories.includes('open_movie'))));
          shortsRow.innerHTML = list.map(m => renderMovieCard(m)).join('');
        }

        // Rail 11: Upcoming Theatrical Trailers
        const trailersRow = document.getElementById('moviesTrailersRow');
        if (trailersRow) {
          const list = allMovies.filter(m => m.isTrailerOnly || m.sourceState === 'TRAILER_ONLY' || m.sourceState === 'UPCOMING_TRAILER' || m.contentType === 'TRAILER' || (m.categories && m.categories.includes('trailers')) || (!m.streamUrl && (!m.episodes || !m.episodes.some(ep => ep.streamUrl)) && m.trailerUrl));
          trailersRow.innerHTML = list.map(m => renderMovieCard(m)).join('');
        }
      });
    });
  });
};

function renderMovieWatchHistory() {
  const section = document.getElementById('moviesContinueSection');
  const row = document.getElementById('moviesContinueRow');
  if (!section || !row) return;

  try {
    const historyIds = JSON.parse(localStorage.getItem('t2l_vod_history') || '[]');
    if (historyIds && historyIds.length > 0) {
      const historyMovies = historyIds.map(id => CatalogProvider.getById(id)).filter(Boolean);
      if (historyMovies.length > 0) {
        row.innerHTML = historyMovies.map(m => renderContinueCard(m)).join('');
        section.style.display = 'block';
        return;
      }
    }
  } catch (e) {}
  section.style.display = 'none';
}

// ==========================================================
// DEDICATED WATCH HISTORY & CONTINUE WATCHING HUB
// ==========================================================
function renderHistoryItemCard(movie) {
  let progressPct = 42;
  let resumeTime = 0;
  try {
    const resumeRaw = localStorage.getItem('t2l_resume_' + movie.id);
    if (resumeRaw) {
      const r = JSON.parse(resumeRaw);
      if (r && r.pct) progressPct = Math.round(r.pct);
      if (r && r.time) resumeTime = Math.round(r.time);
    }
  } catch (e) {}
  if (progressPct < 5) progressPct = 5;
  if (progressPct > 98) progressPct = 95;

  const thumb = movie.backdropUrl || movie.posterUrl || 'assets/placeholder.png';
  const duration = movie.durationFormatted || (movie.isWebSeries ? 'Episodic' : 'Feature');
  const minutesLeft = resumeTime > 0 ? `${Math.round(resumeTime / 60)} min watched` : `${progressPct}% completed`;

  return `
    <div class="history-item-card" style="background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255,255,255,0.08); border-radius: 14px; overflow: hidden; display: flex; flex-direction: column; transition: all 0.2s ease; box-shadow: 0 4px 16px rgba(0,0,0,0.35);">
      <div style="position: relative; aspect-ratio: 16/9; background: #000; overflow: hidden; cursor: pointer;" onclick="openMovieDetails('${movie.id}')">
        <img src="${thumb}" alt="${movie.title}" style="width: 100%; height: 100%; object-fit: cover;" onerror="this.onerror=null; this.src='assets/placeholder.png';" loading="lazy">
        <div style="position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.7) 100%);"></div>
        <div style="position: absolute; top: 8px; right: 8px; z-index: 2;">
          <button onclick="event.stopPropagation(); removeHistoryItem('${movie.id}')" title="Remove from History" style="background: rgba(0,0,0,0.65); border: 1px solid rgba(255,255,255,0.2); color: #e2e8f0; width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; cursor: pointer; transition: all 0.2s;">
            ✕
          </button>
        </div>
        <div style="position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;">
          <div style="width: 44px; height: 44px; border-radius: 50%; background: rgba(16, 185, 129, 0.9); display: flex; align-items: center; justify-content: center; box-shadow: 0 4px 15px rgba(16,185,129,0.4);">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="#fff" style="margin-left: 2px;"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg>
          </div>
        </div>
        <!-- Progress bar container -->
        <div style="position: absolute; bottom: 0; left: 0; right: 0; height: 4px; background: rgba(255,255,255,0.2);">
          <div style="width: ${progressPct}%; height: 100%; background: #10B981; border-radius: 0 2px 2px 0;"></div>
        </div>
      </div>
      <div style="padding: 12px 14px; display: flex; flex-direction: column; gap: 6px; flex: 1;">
        <div style="display: flex; align-items: center; justify-content: space-between; gap: 8px;">
          <h4 style="font-size: 15px; font-weight: 700; color: #fff; margin: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${movie.title}</h4>
          <span style="font-size: 11px; font-weight: 700; color: #10B981; background: rgba(16,185,129,0.12); padding: 2px 6px; border-radius: 4px; white-space: nowrap;">${progressPct}%</span>
        </div>
        <div style="font-size: 12px; color: #94a3b8; display: flex; align-items: center; gap: 6px;">
          <span>${movie.year || '2024'}</span>
          <span>•</span>
          <span>${duration}</span>
          <span>•</span>
          <span style="color: #cbd5e1;">${minutesLeft}</span>
        </div>
        <div style="display: flex; gap: 8px; margin-top: 8px;">
          <button onclick="openMovieDetails('${movie.id}')" style="flex: 1; background: #10B981; color: #fff; border: none; padding: 7px 12px; border-radius: 8px; font-size: 12.5px; font-weight: 700; display: flex; align-items: center; justify-content: center; gap: 6px; cursor: pointer;">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="#fff"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg>
            Resume
          </button>
          <button onclick="openMovieDetails('${movie.id}')" style="background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.12); color: #cbd5e1; padding: 7px 12px; border-radius: 8px; font-size: 12.5px; font-weight: 600; cursor: pointer;">
            Details
          </button>
        </div>
      </div>
    </div>
  `;
}

window.openWatchHistoryPage = async function(fromPage) {
  window.lastBrowsePage = fromPage || currentActivePage || 'home';
  await CatalogProvider.load();
  renderWatchHistoryPageUI();
  switchPage('history');
};

window.renderWatchHistoryPageUI = function() {
  const grid = document.getElementById('historyCardsGrid');
  const empty = document.getElementById('historyEmptyState');
  const clearBtn = document.getElementById('btnClearWatchHistory');
  if (!grid) return;

  let historyIds = [];
  try {
    historyIds = JSON.parse(localStorage.getItem('t2l_vod_history') || '[]');
  } catch (e) {}

  let historyMovies = historyIds.map(id => CatalogProvider.getById(id)).filter(Boolean);

  if (historyMovies.length === 0) {
    // Show starter bookmark recommendations if history is empty
    const defaultIds = ['series_panchayat', 'vod_jawan', 'vod_kalki_2898_ad', 'series_mirzapur'];
    const defaults = defaultIds.map(id => CatalogProvider.getById(id)).filter(Boolean);
    if (defaults.length > 0) {
      grid.innerHTML = defaults.map(m => renderHistoryItemCard(m)).join('');
      if (empty) empty.style.display = 'none';
      if (clearBtn) clearBtn.style.display = 'inline-flex';
    } else {
      grid.innerHTML = '';
      if (empty) empty.style.display = 'block';
      if (clearBtn) clearBtn.style.display = 'none';
    }
  } else {
    grid.innerHTML = historyMovies.map(m => renderHistoryItemCard(m)).join('');
    if (empty) empty.style.display = 'none';
    if (clearBtn) clearBtn.style.display = 'inline-flex';
  }
};

window.removeHistoryItem = function(movieId) {
  try {
    let historyIds = JSON.parse(localStorage.getItem('t2l_vod_history') || '[]');
    historyIds = historyIds.filter(id => id !== movieId);
    localStorage.setItem('t2l_vod_history', JSON.stringify(historyIds));
    localStorage.removeItem('t2l_resume_' + movieId);
  } catch (e) {}
  renderWatchHistoryPageUI();
  renderMovieWatchHistory();
  const homeContinueRow = document.getElementById('homeMovieContinueRow');
  if (homeContinueRow && typeof renderHomeCinemaRows === 'function') {
    renderHomeCinemaRows();
  }
  showToast('Removed from continue watching');
};

window.clearAllWatchHistory = function() {
  if (confirm('Clear all playback history and progress bookmarks?')) {
    try {
      localStorage.removeItem('t2l_vod_history');
      Object.keys(localStorage).forEach(k => {
        if (k.startsWith('t2l_resume_')) localStorage.removeItem(k);
      });
    } catch (e) {}
    renderWatchHistoryPageUI();
    renderMovieWatchHistory();
    const section = document.getElementById('homeMovieContinueSection');
    if (section) section.style.display = 'none';
    showToast('Watch history cleared');
  }
};

// ==========================================================
// DEDICATED CATEGORY & COLLECTION PAGE ROUTER
// ==========================================================
window.currentCollectionKey = 'all';
window.currentCollectionItems = [];
window.currentCollectionOriginalItems = [];

window.openCategoryPage = async function(catKey, title, kicker, fromPage) {
  window.lastBrowsePage = fromPage || currentActivePage || 'home';
  window.currentCollectionKey = catKey;

  await CatalogProvider.load();
  const allMovies = CatalogProvider.getAll();

  let filtered = [];
  if (catKey === 'Shorts' || catKey === 'shorts') {
    filtered = allMovies.filter(m => m.isShortFilm || (m.categories && (m.categories.includes('short') || m.categories.includes('open_movie'))));
  } else if (catKey === 'Trailers' || catKey === 'trailers') {
    filtered = allMovies.filter(m => m.isTrailerOnly || m.sourceState === 'TRAILER_ONLY' || m.sourceState === 'UPCOMING_TRAILER' || m.contentType === 'TRAILER' || (m.categories && m.categories.includes('trailers')) || (!m.streamUrl && (!m.episodes || !m.episodes.some(ep => ep.streamUrl)) && m.trailerUrl));
  } else if (catKey === 'premieres' || catKey === 'theatrical') {
    filtered = allMovies.filter(m => m.featured || m.isTheatrical || (m.badge && m.badge.includes('Premiere')) || m.year >= 2024);
  } else if (catKey === 'Action' || catKey === 'action') {
    filtered = allMovies.filter(m => (m.categories && m.categories.includes('action')) || (m.genres && m.genres.some(g => g.toLowerCase().includes('action'))));
  } else if (catKey === 'Thrillers' || catKey === 'thrillers') {
    filtered = allMovies.filter(m => (m.categories && m.categories.includes('thriller')) || (m.genres && m.genres.some(g => g.toLowerCase().includes('thriller'))));
  } else if (catKey === 'Classics' || catKey === 'classics') {
    filtered = allMovies.filter(m => (m.categories && (m.categories.includes('classics') || m.categories.includes('heritage'))) || m.year < 2000);
  } else {
    filtered = CatalogProvider.filterByCategory(catKey);
  }

  window.currentCollectionOriginalItems = filtered;
  window.currentCollectionItems = [...filtered];

  const titleEl = document.getElementById('collectionPageTitle');
  const kickerEl = document.getElementById('collectionPageKicker');
  const countEl = document.getElementById('collectionPageCount');
  const searchInput = document.getElementById('collectionSearchInput');
  const sortSelect = document.getElementById('collectionSortSelect');

  if (titleEl) titleEl.textContent = title || catKey;
  if (kickerEl) kickerEl.textContent = kicker || 'CURATED COLLECTION';
  if (countEl) countEl.textContent = `${filtered.length} Titles`;
  if (searchInput) searchInput.value = '';
  if (sortSelect) sortSelect.value = 'featured';

  renderCollectionCatalogGrid();
  switchPage('collection');
};

window.renderCollectionCatalogGrid = function() {
  const grid = document.getElementById('collectionCatalogGrid');
  const empty = document.getElementById('collectionEmptyState');
  if (!grid) return;

  const items = window.currentCollectionItems || [];
  if (items.length === 0) {
    grid.innerHTML = '';
    if (empty) empty.style.display = 'block';
  } else {
    if (empty) empty.style.display = 'none';
    grid.innerHTML = items.map(m => renderMovieCard(m)).join('');
  }
};

window.handleCollectionSearch = function(query) {
  const orig = window.currentCollectionOriginalItems || [];
  if (!query || !query.trim()) {
    window.currentCollectionItems = [...orig];
  } else {
    const q = query.toLowerCase().trim();
    window.currentCollectionItems = orig.filter(m => {
      const matchTitle = m.title && m.title.toLowerCase().includes(q);
      const castStr = Array.isArray(m.cast) ? m.cast.join(' ').toLowerCase() : String(m.cast || '').toLowerCase();
      const matchCast = castStr.includes(q);
      const genreStr = Array.isArray(m.genres) ? m.genres.join(' ').toLowerCase() : String(m.genre || '').toLowerCase();
      const matchGenre = genreStr.includes(q);
      return matchTitle || matchCast || matchGenre;
    });
  }
  const countEl = document.getElementById('collectionPageCount');
  if (countEl) countEl.textContent = `${window.currentCollectionItems.length} Titles`;
  renderCollectionCatalogGrid();
};

window.handleCollectionSort = function(sortBy) {
  const items = window.currentCollectionItems || [];
  if (sortBy === 'newest') {
    items.sort((a, b) => (b.year || 0) - (a.year || 0));
  } else if (sortBy === 'rating') {
    items.sort((a, b) => (b.rating || 0) - (a.rating || 0));
  } else if (sortBy === 'title') {
    items.sort((a, b) => (a.title || '').localeCompare(b.title || ''));
  } else {
    // featured: restore original order
    const orig = window.currentCollectionOriginalItems || [];
    const origMap = new Map(orig.map((item, idx) => [item.id, idx]));
    items.sort((a, b) => (origMap.get(a.id) ?? 0) - (origMap.get(b.id) ?? 0));
  }
  renderCollectionCatalogGrid();
};

window.returnFromCollectionOrHistory = function() {
  const returnTo = window.lastBrowsePage || 'home';
  window.switchPage(returnTo);
};

window.filterMovieCategory = function(cat, chipEl) {
  document.querySelectorAll('.cinema-mode-btn').forEach(c => c.classList.remove('active'));
  if (chipEl) chipEl.classList.add('active');

  if (cat === 'all') {
    const rowsContainer = document.getElementById('moviesRowsContainer');
    const heroSection = document.getElementById('cinemaHeroSection') || document.getElementById('moviesHeroSection');
    const gridSection = document.getElementById('moviesGridSection');
    if (gridSection) gridSection.style.display = 'none';
    if (heroSection) heroSection.style.display = 'flex';
    if (rowsContainer) rowsContainer.style.display = 'block';
    window.scrollTo({ top: 0, behavior: 'smooth' });
    return;
  }

  const catTitles = {
    'Shorts': { title: 'Short Movies (4K Ultra HD)', kicker: '4K ULTRA HD • CURATED SHORTS' },
    'shorts': { title: 'Short Movies (4K Ultra HD)', kicker: '4K ULTRA HD • CURATED SHORTS' },
    'Bollywood': { title: 'Bollywood Blockbusters', kicker: 'HINDI FIRST • BLOCKBUSTERS' },
    'Web-Series': { title: 'Acclaimed Web-Series & Sagas', kicker: 'FULL EPISODES • BINGE WORTHY' },
    'sagas': { title: 'Acclaimed Web-Series & Sagas', kicker: 'FULL EPISODES • BINGE WORTHY' },
    'Asian': { title: 'K-Drama & Asian Sagas (Hindi Dubbed)', kicker: 'HINDI DUBBED • ASIAN SAGAS' },
    'Hollywood': { title: 'Hollywood & Worldwide Hits', kicker: 'WORLDWIDE HITS • DUAL AUDIO' },
    'Trailers': { title: 'Official Theatrical Trailers', kicker: '4K PREVIEWS • THEATRICAL TEASERS' },
    'trailers': { title: 'Official Theatrical Trailers', kicker: '4K PREVIEWS • THEATRICAL TEASERS' },
    'premieres': { title: 'Theatrical Premieres & Spotlight', kicker: 'CINEMATIC HORIZONS' },
    'theatrical': { title: 'Theatrical Premieres & Spotlight', kicker: 'CINEMATIC HORIZONS' },
    'Anime': { title: 'Anime & Animation Legends', kicker: 'ANIMATED WORLDS' },
    'Thrillers': { title: 'High-Stakes Thrillers & Mystery', kicker: 'PULSE-POUNDING' },
    'Action': { title: 'High-Octane Action Blockbusters', kicker: 'ADRENALINE & ACTION' },
    'watchlist': { title: 'Continue Watching', kicker: 'PLAYBACK PROGRESS' }
  };

  const meta = catTitles[cat] || { title: cat + ' Collection', kicker: 'CURATED COLLECTION' };
  openCategoryPage(cat, meta.title, meta.kicker, 'movies');
};
window.filterCinemaMode = window.filterMovieCategory;

let _movieSearchDebounceTimer = null;
window.handleMovieSearch = function(query) {
  const rowsContainer = document.getElementById('moviesRowsContainer');
  const heroSection = document.getElementById('cinemaHeroSection') || document.getElementById('moviesHeroSection');
  const gridSection = document.getElementById('moviesGridSection');
  const gridTitle = document.getElementById('moviesGridTitle');
  const catalogGrid = document.getElementById('moviesCatalogGrid');

  if (!query || !query.trim()) {
    if (_movieSearchDebounceTimer) {
      clearTimeout(_movieSearchDebounceTimer);
      _movieSearchDebounceTimer = null;
    }
    if (rowsContainer) rowsContainer.style.display = 'block';
    if (heroSection) heroSection.style.display = 'flex';
    if (gridSection) {
      gridSection.classList.remove('is-searching');
      gridSection.style.display = 'none';
    }
    return;
  }

  if (_movieSearchDebounceTimer) clearTimeout(_movieSearchDebounceTimer);
  _movieSearchDebounceTimer = setTimeout(() => {
    const results = CatalogProvider.search(query);
    if (rowsContainer) rowsContainer.style.display = 'none';
    if (heroSection) heroSection.style.display = 'none';
    if (gridSection) {
      gridSection.classList.add('is-searching');
      gridSection.style.display = 'block';
    }
    if (gridTitle) gridTitle.textContent = `Search Results: "${query}" (${results.length})`;
    if (catalogGrid) {
      if (results.length === 0) {
        catalogGrid.innerHTML = `
          <div style="grid-column: 1 / -1; padding: 32px 16px; text-align: center; color: #94a3b8;">
            <p style="font-size: 16px; margin-bottom: 6px;">🔍 No movies found</p>
            <p style="font-size: 12px; color: #64748b;">Try searching for "Kalki", "Jawan", "Panchayat", or "Oppenheimer"</p>
          </div>
        `;
      } else {
        catalogGrid.innerHTML = results.map(m => renderMovieCard(m)).join('');
      }
    }
  }, 100);
};

function renderEpisodeItemMarkup(movie, ep) {
  const isTorrentPlayable = (ep.sourceState === 'TORRENT_SOURCE_AVAILABLE' || (!ep.sourceState && ep.season === 1)) && !!movie.torrentUri;
  const isDirect = Boolean(ep.streamUrl || isTorrentPlayable);

  let state = 'NO_AUTHORIZED_SOURCE';
  if (ep.sourceState === 'SOURCE_OFFLINE' || ep.sourceState === 'OFFLINE') {
    state = 'SOURCE_OFFLINE';
  } else if (ep.sourceState === 'UPCOMING' || ep.episodeType === 'upcoming' || movie.sourceState === 'UPCOMING' || (movie.year && parseInt(movie.year) >= 2026 && !isDirect)) {
    state = 'UPCOMING';
  } else if (isDirect && ep.sourceState !== 'NO_AUTHORIZED_SOURCE' && ep.episodeType !== 'no_authorized_source') {
    state = 'PLAYABLE_FULL_EPISODE';
  } else if (ep.sourceState === 'TRAILER_ONLY' || ep.episodeType === 'trailer' || (movie.trailerUrl && (movie.sourceState === 'TRAILER_ONLY' || ep.isTrailer))) {
    state = 'TRAILER_ONLY';
  } else {
    state = 'NO_AUTHORIZED_SOURCE';
  }

  const epTitleEscaped = (ep.title || '').replace(/'/g, "\\'");
  const movieTitleEscaped = (movie.title || '').replace(/'/g, "\\'");
  const fullTitle = `${movieTitleEscaped} - ${epTitleEscaped}`;

  if (state === 'PLAYABLE_FULL_EPISODE') {
    const qBadge = ep.qualityHonestBadge ? `<span style="font-size: 10px; background: rgba(34,197,94,0.15); color: #4ade80; border: 1px solid rgba(34,197,94,0.3); border-radius: 4px; padding: 1px 6px; font-weight: 600; margin-left: 6px;">${ep.qualityHonestBadge}</span>` : '';
    return `
      <div class="series-ep-item" onclick="playSeriesEpisode('${movie.id}', '${ep.id}')">
        <div class="series-ep-left">
          <span class="series-ep-play-icon" style="color: #4ade80;">▶</span>
          <div class="series-ep-info">
            <div style="display: flex; align-items: center;">
              <span class="series-ep-title">${ep.title}</span>
              ${qBadge}
            </div>
            <span class="series-ep-duration">${ep.duration || ''} • Full Episode</span>
          </div>
        </div>
        <button type="button" class="series-ep-play-btn" onclick="event.stopPropagation(); playSeriesEpisode('${movie.id}', '${ep.id}')">Stream</button>
      </div>
    `;
  } else if (state === 'TRAILER_ONLY') {
    const trailerTarget = movie.trailerUrl || ep.streamUrl;
    return `
      <div class="series-ep-item" onclick="startMovieStream('${movie.id}', '${trailerTarget}', '${fullTitle} (Trailer)', true, '${ep.id}')">
        <div class="series-ep-left">
          <span class="series-ep-play-icon" style="color: #60a5fa;">🎬</span>
          <div class="series-ep-info">
            <span class="series-ep-title">${ep.title}</span>
            <span class="series-ep-duration" style="color: #94a3b8;">${ep.duration || '2m'} • Official Trailer</span>
          </div>
        </div>
        <button type="button" class="series-ep-play-btn" style="background: rgba(59, 130, 246, 0.2); border-color: rgba(96, 165, 250, 0.4); color: #93c5fd;" onclick="event.stopPropagation(); startMovieStream('${movie.id}', '${trailerTarget}', '${fullTitle} (Trailer)', true, '${ep.id}')">Trailer</button>
      </div>
    `;
  } else if (state === 'UPCOMING') {
    return `
      <div class="series-ep-item series-ep-unavailable" onclick="showToast('${movieTitleEscaped}: ${epTitleEscaped} is an upcoming release scheduled for ${movie.year || '2026'}.')">
        <div class="series-ep-left">
          <span class="series-ep-play-icon" style="color: #f59e0b;">📅</span>
          <div class="series-ep-info">
            <span class="series-ep-title" style="color: #cbd5e1;">${ep.title}</span>
            <span class="series-ep-duration" style="color: #fbbf24;">Release Scheduled • ${movie.year || '2026'}</span>
          </div>
        </div>
        <span class="series-ep-badge-unavail" style="background: rgba(245, 158, 11, 0.15); color: #fbbf24; border: 1px solid rgba(245, 158, 11, 0.3); border-radius: 4px; padding: 2px 8px; font-size: 11px;">Upcoming</span>
      </div>
    `;
  } else if (state === 'SOURCE_OFFLINE') {
    return `
      <div class="series-ep-item series-ep-unavailable" onclick="showToast('${movieTitleEscaped}: ${epTitleEscaped} mirror is temporarily offline. Verifying next update.')">
        <div class="series-ep-left">
          <span class="series-ep-play-icon" style="color: #ef4444;">⚠️</span>
          <div class="series-ep-info">
            <span class="series-ep-title" style="color: #cbd5e1;">${ep.title}</span>
            <span class="series-ep-duration" style="color: #f87171;">Mirror Offline • Verification Pending</span>
          </div>
        </div>
        <span class="series-ep-badge-unavail" style="background: rgba(239, 68, 68, 0.15); color: #f87171; border: 1px solid rgba(239, 68, 68, 0.3); border-radius: 4px; padding: 2px 8px; font-size: 11px;">Offline</span>
      </div>
    `;
  } else {
    // NO_AUTHORIZED_SOURCE
    return `
      <div class="series-ep-item series-ep-unavailable" onclick="showToast('No authorized public stream for ${fullTitle}. Loading Instant Streamer...'); if (typeof openInstantStreamerForContent === 'function') openInstantStreamerForContent('${fullTitle}');">
        <div class="series-ep-left">
          <span class="series-ep-play-icon" style="color: #a855f7;">⚡</span>
          <div class="series-ep-info">
            <span class="series-ep-title" style="color: #e2e8f0;">${ep.title}</span>
            <span class="series-ep-duration" style="color: #c084fc;">No Public Stream Available • Use Instant Streamer</span>
          </div>
        </div>
        <button type="button" class="series-ep-play-btn" style="background: rgba(168, 85, 247, 0.2); border-color: rgba(168, 85, 247, 0.4); color: #d8b4fe; font-size: 11px; padding: 4px 10px;" onclick="event.stopPropagation(); showToast('No authorized public stream for ${fullTitle}. Loading Instant Streamer...'); if (typeof openInstantStreamerForContent === 'function') openInstantStreamerForContent('${fullTitle}');">Custom</button>
      </div>
    `;
  }
}

let _movieModalPhase2Timer = null;

window.openMovieDetails = function(movieId) {
  const movie = CatalogProvider.getById(movieId);
  if (!movie) return;
  currentSelectedMovie = movie;

  const modal = document.getElementById('movieDetailsModal');
  if (!modal) return;

  if (_movieModalCloseTimer) {
    clearTimeout(_movieModalCloseTimer);
    _movieModalCloseTimer = null;
  }
  if (_movieModalPhase2Timer) {
    clearTimeout(_movieModalPhase2Timer);
    _movieModalPhase2Timer = null;
  }

  // Phase 1 (Immediate, T = 0ms): Critical visible hero fields only
  const posterImg = document.getElementById('movieDetailsPosterImg');
  const title = document.getElementById('movieDetailsTitle');
  const year = document.getElementById('movieDetailsYear');
  const duration = document.getElementById('movieDetailsDuration');
  const resolution = document.getElementById('movieDetailsResolution');
  const categoryChip = document.getElementById('movieDetailsCategoryChip');
  const btnStream = document.getElementById('btnMovieStream');
  const btnStreamText = document.getElementById('btnMovieStreamText');
  const btnTrailer = document.getElementById('btnMovieTrailer');

  if (posterImg) {
    posterImg.onerror = function() { this.onerror = null; this.src = 'assets/placeholder.png'; };
    posterImg.alt = movie.title || 'Movie Poster';
    // Defer image src update to frame 1 so compositor can start entrance immediately on frame 0
    requestAnimationFrame(() => {
      posterImg.src = movie.posterUrl || 'assets/placeholder.png';
    });
  }
  if (title) title.textContent = movie.title;
  if (year) year.textContent = movie.year || '2024';
  if (duration) {
    if (movie.isShortFilm || (movie.categories && movie.categories.includes('short'))) {
      duration.textContent = movie.durationFormatted || 'Short Film';
    } else if (movie.isTrailerOnly || movie.sourceState === 'TRAILER_ONLY' || movie.sourceState === 'UPCOMING_TRAILER') {
      duration.textContent = 'Official Trailer';
    } else {
      duration.textContent = movie.durationFormatted || 'Feature';
    }
  }
  if (resolution) {
    if (movie.sourceState === 'NO_AUTHORIZED_SOURCE') {
      resolution.textContent = movie.trailerUrl ? 'Official Trailer' : 'Custom Stream';
    } else if (movie.isTrailerOnly || movie.sourceState === 'TRAILER_ONLY' || movie.sourceState === 'UPCOMING_TRAILER') {
      resolution.textContent = 'Official Trailer';
    } else if (movie.isShortFilm || (movie.categories && movie.categories.includes('short'))) {
      resolution.textContent = (movie.qualityHonestBadge || '4K UHD') + ' • Short Film';
    } else {
      let rText = movie.qualityHonestBadge || (movie.resolution ? movie.resolution.split(' ')[0] : '1080p');
      if (movie.streamUrl && rText.toLowerCase().includes('trailer')) {
        rText = (movie.qualityClass === 'FULL HD' ? '1080p FHD' : (movie.qualityClass === 'HD' ? '720p HD' : '480p SD'));
      }
      resolution.textContent = rText;
    }
  }
  if (categoryChip) {
    if (movie.isShortFilm || (movie.categories && movie.categories.includes('short'))) {
      categoryChip.textContent = 'Open Short Film';
    } else if (movie.isTrailerOnly || movie.sourceState === 'TRAILER_ONLY' || movie.sourceState === 'UPCOMING_TRAILER') {
      categoryChip.textContent = 'Official Trailer';
    } else {
      categoryChip.textContent = movie.mediaType === 'series' ? 'Web-Series' : (movie.type || 'Cinema');
    }
  }

  // Primary stream action button setup
  const sState = movie.sourceState || (movie.streamUrl ? 'DIRECT_STREAM_AVAILABLE' : (movie.trailerUrl ? 'TRAILER_ONLY' : (movie.torrentUri ? 'TORRENT_SOURCE_AVAILABLE' : 'NO_AUTHORIZED_SOURCE')));
  const isDirect = (sState === 'DIRECT_STREAM_AVAILABLE' || !!movie.streamUrl);
  const isTrailerOnly = (sState === 'TRAILER_ONLY' || (!!movie.trailerUrl && !movie.streamUrl));

  if (btnTrailer) {
    btnTrailer.style.display = (movie.trailerUrl && isDirect) ? 'inline-flex' : 'none';
  }
  if (btnStream) {
    btnStream.disabled = false;
    btnStream.style.opacity = '1';
    btnStream.style.pointerEvents = 'auto';
    if (isDirect) {
      btnStream.className = 'movie-detail-master-cta movie-btn-stream direct-stream';
      if (btnStreamText) btnStreamText.textContent = movie.mediaType === 'series' ? 'STREAM SERIES' : 'STREAM DIRECT';
    } else if (isTrailerOnly) {
      btnStream.className = 'movie-detail-master-cta movie-btn-stream trailer-stream';
      if (btnStreamText) btnStreamText.textContent = 'WATCH TRAILER';
    } else {
      btnStream.className = 'movie-detail-master-cta movie-btn-stream custom-stream';
      if (btnStreamText) btnStreamText.textContent = 'WATCH NOW';
    }
  }

  // Launch compositor-only entrance transition immediately!
  modal.classList.remove('is-closing');
  modal.classList.add('active');

  // Defer body lock to after entrance finishes to prevent root viewport reflow during animation
  setTimeout(() => {
    if (modal && modal.classList.contains('active')) {
      document.body.classList.add('modal-open-locked');
    }
  }, 280);

  // Phase 2 (Deferred, T = 280ms): Populate secondary metadata strictly AFTER entrance animation completes
  _movieModalPhase2Timer = setTimeout(() => {
    if (!modal || !modal.classList.contains('active') || currentSelectedMovie !== movie) return;
    requestAnimationFrame(() => {
      populateMovieDetailsPhase2(movie);
    });
  }, 280);
};

function populateMovieDetailsPhase2(movie) {
  const backdrop = document.getElementById('movieDetailsBackdrop');
  if (backdrop) {
    // Async backdrop load after metadata layout
    requestAnimationFrame(() => {
      backdrop.style.backgroundImage = `url('${movie.backdropUrl || movie.posterUrl || "assets/placeholder.png"}')`;
    });
  }

  const swarmBadge = document.getElementById('movieDetailsSwarmBadge');
  const swarmText = document.getElementById('movieDetailsSwarmText');
  if (swarmBadge) {
    if (movie.torrentUri && movie.swarmSeeders) {
      swarmBadge.style.display = 'inline-flex';
      const seeders = movie.swarmSeeders;
      if (seeders >= 80) {
        swarmBadge.className = 'movie-swarm-badge swarm-excellent';
        if (swarmText) swarmText.textContent = `Swarm: High Health (${seeders}+ Seeders)`;
      } else if (seeders >= 40) {
        swarmBadge.className = 'movie-swarm-badge swarm-good';
        if (swarmText) swarmText.textContent = `Swarm: Moderate (${seeders}+ Seeders)`;
      } else {
        swarmBadge.className = 'movie-swarm-badge swarm-poor';
        if (swarmText) swarmText.textContent = `Swarm: Low Swarm (${seeders} Seeders)`;
      }
    } else {
      swarmBadge.style.display = 'none';
    }
  }

  const specCodec = document.getElementById('movieSpecCodec');
  const specAudio = document.getElementById('movieSpecAudio');
  const specSize = document.getElementById('movieSpecSize');
  const specLicense = document.getElementById('movieSpecLicense');
  const pillCodec = document.getElementById('specPillCodec');
  const pillAudio = document.getElementById('specPillAudio');
  const pillRes = document.getElementById('specPillRes');
  const pillSize = document.getElementById('specPillSize');
  const pillLicense = document.getElementById('specPillLicense');
  const specResVal = document.getElementById('movieSpecResVal');

  if (movie.codec) {
    if (specCodec) specCodec.textContent = movie.codec;
    if (pillCodec) pillCodec.style.display = 'flex';
  } else if (movie.streamUrl) {
    if (specCodec) specCodec.textContent = 'H.264 / AVC';
    if (pillCodec) pillCodec.style.display = 'flex';
  } else {
    if (pillCodec) pillCodec.style.display = 'none';
  }

  let audioDisplay = '';
  if (typeof movie.audio === 'string') {
    audioDisplay = movie.audio;
  } else if (movie.audio && typeof movie.audio === 'object') {
    if (movie.audio.primaryLanguage) {
      audioDisplay = movie.audio.primaryLanguage;
    } else if (movie.audio.availableLanguages && movie.audio.availableLanguages.length > 0) {
      audioDisplay = movie.audio.availableLanguages.join(', ');
    }
  } else if (movie.languages && movie.languages.length > 0) {
    audioDisplay = movie.languages.join(', ');
  } else if (movie.defaultLanguage) {
    audioDisplay = movie.defaultLanguage;
  }
  if (audioDisplay) {
    if (specAudio) specAudio.textContent = audioDisplay;
    if (pillAudio) pillAudio.style.display = 'flex';
  } else {
    if (pillAudio) pillAudio.style.display = 'none';
  }

  const resVal = movie.resolution || movie.qualityHonestBadge;
  if (resVal && !resVal.toLowerCase().includes('trailer') && !resVal.toLowerCase().includes('unavailable')) {
    if (specResVal) specResVal.textContent = resVal;
    if (pillRes) pillRes.style.display = 'flex';
  } else {
    if (pillRes) pillRes.style.display = 'none';
  }

  if (movie.fileSize) {
    if (specSize) specSize.textContent = movie.fileSize;
    if (pillSize) pillSize.style.display = 'flex';
  } else {
    if (pillSize) pillSize.style.display = 'none';
  }

  if (movie.license) {
    if (specLicense) specLicense.textContent = movie.license.split('(')[0].trim();
    if (pillLicense) pillLicense.style.display = 'flex';
  } else if (movie.region === 'PUBLIC_DOMAIN') {
    if (specLicense) specLicense.textContent = 'Public Domain';
    if (pillLicense) pillLicense.style.display = 'flex';
  } else {
    if (pillLicense) pillLicense.style.display = 'none';
  }

  const desc = document.getElementById('movieDetailsDesc');
  const director = document.getElementById('movieDetailsDirector');
  const genres = document.getElementById('movieDetailsGenres');
  const cast = document.getElementById('movieDetailsCast');
  if (desc) desc.textContent = movie.description || '';
  if (director) director.textContent = movie.director || 'Various Artists';
  if (genres) genres.textContent = movie.genres ? movie.genres.join(', ') : 'Cinema';
  if (cast) cast.textContent = movie.cast || 'Cast Details in Credits';

  // Honest Audio Tracks & Language Selection
  const languagesListEl = document.getElementById('movieDetailsLanguagesList');
  const activeLangBadge = document.getElementById('movieDetailsActiveLangBadge');
  const hasMultipleStreams = (movie.audioStreams && Object.keys(movie.audioStreams).length > 1) ||
    (movie.seasons && movie.seasons.some(s => s.episodes && s.episodes.some(e => e.audioStreams && Object.keys(e.audioStreams).length > 1)));
  const isHls = Boolean(movie.streamUrl && movie.streamUrl.includes('.m3u8'));
  const canSwitchAudio = hasMultipleStreams || isHls;

  let langs = [];
  if (hasMultipleStreams) {
    const streamsMap = movie.audioStreams || (movie.seasons && movie.seasons[0].episodes[0].audioStreams);
    langs = Object.keys(streamsMap);
  } else if (movie.languages && movie.languages.length > 0) {
    langs = movie.languages;
  } else {
    langs = [movie.defaultLanguage || (movie.audioClassification === 'NON_HINDI_AUDIO' ? 'English' : 'Hindi')];
  }

  const savedPref = localStorage.getItem('t2l_preferred_movie_audio_lang');
  let chosenLang = 'Hindi';
  if (savedPref && langs.includes(savedPref)) {
    chosenLang = savedPref;
  } else if (langs.includes('Hindi')) {
    chosenLang = 'Hindi';
  } else if (movie.defaultLanguage && langs.includes(movie.defaultLanguage)) {
    chosenLang = movie.defaultLanguage;
  } else {
    chosenLang = langs[0];
  }
  window.selectedMovieAudioLang = chosenLang;

  if (activeLangBadge) {
    if (movie.audioClassification === 'HINDI_AUDIO') {
      activeLangBadge.textContent = '🇮🇳 Hindi Audio (Master)';
    } else if (movie.audioClassification === 'MULTI_AUDIO_INCLUDING_HINDI' && canSwitchAudio) {
      activeLangBadge.textContent = `🌐 Multi-Audio (${chosenLang} Selected)`;
    } else if (movie.audioClassification === 'HINDI_SUBTITLE_ONLY') {
      activeLangBadge.textContent = `💬 ${chosenLang} Audio • Hindi Subs`;
    } else if (movie.audioClassification === 'NON_HINDI_AUDIO') {
      activeLangBadge.textContent = `🌐 ${chosenLang} Audio (Non-Hindi)`;
    } else {
      activeLangBadge.textContent = chosenLang + ' Audio';
    }
  }

  if (languagesListEl) {
    const langIcons = {
      'Hindi': '🇮🇳', 'Telugu': '🇮🇳', 'Tamil': '🇮🇳', 'Kannada': '🇮🇳',
      'Malayalam': '🇮🇳', 'Marathi': '🇮🇳', 'English': '🌐', 'Korean': '🎧',
      'Japanese': '🎧', 'Universal Audio': '🎵'
    };
    languagesListEl.innerHTML = langs.map(l => {
      const isSelected = (l === chosenLang);
      const icon = langIcons[l] || '🎧';
      const clickableStyle = canSwitchAudio ? 'cursor: pointer;' : 'cursor: default; opacity: 0.9;';
      return `
        <button type="button" 
                class="movie-lang-pill ${isSelected ? 'active' : ''}" 
                ${canSwitchAudio ? `onclick="selectMovieDetailsLang('${l}', this)"` : ''}
                style="display: inline-flex; align-items: center; gap: 6px; padding: 6px 14px; border-radius: 9999px; font-size: 12px; font-weight: 600; ${clickableStyle} transition: all 0.2s; border: 1px solid ${isSelected ? 'rgba(34, 211, 238, 0.45)' : 'rgba(255,255,255,0.1)'}; background: ${isSelected ? 'rgba(34, 211, 238, 0.16)' : 'rgba(255,255,255,0.05)'}; color: ${isSelected ? '#22D3EE' : '#cbd5e1'};">
          <span>${icon}</span>
          <span>${l}</span>
          ${isSelected ? '<span class="check-icon" style="font-size: 10px; color: #22D3EE;">✓</span>' : ''}
        </button>
      `;
    }).join('');
  }

  // Quality selector pills
  const qualitySec = document.getElementById('movieQualitySelectorSection');
  const qualityContainer = document.getElementById('movieQualityPillsContainer');
  const qualityBadge = document.getElementById('movieDetailsActiveQualityBadge');
  window.selectedMovieStreamQuality = 'auto';

  const sStateNow = movie.sourceState || (movie.streamUrl ? 'DIRECT_STREAM_AVAILABLE' : (movie.trailerUrl ? 'TRAILER_ONLY' : (movie.torrentUri ? 'TORRENT_SOURCE_AVAILABLE' : 'NO_AUTHORIZED_SOURCE')));

  if (qualitySec && qualityContainer) {
    if (sStateNow === 'NO_AUTHORIZED_SOURCE') {
      qualitySec.style.display = 'none';
    } else {
      qualitySec.style.display = 'block';
      let qOptions = [];
      if (movie.streamUrl && movie.streamUrl.includes('.m3u8')) {
        qOptions = [
          { key: 'auto', label: 'Auto (Dynamic Adaptive)', badge: 'ABR' },
          { key: '1080p', label: '1080p Full HD', badge: '1080p' },
          { key: '720p', label: '720p HD', badge: '720p' },
          { key: '480p', label: '480p SD', badge: '480p' }
        ];
      } else if (sStateNow === 'DIRECT_STREAM_AVAILABLE' || !!movie.streamUrl) {
        let honestRes = movie.qualityHonestBadge || (movie.qualityClass === 'FULL HD' ? '1080p HD' : (movie.qualityClass === 'HD' ? '720p HD' : '480p SD'));
        if (honestRes.toLowerCase().includes('trailer')) {
          honestRes = (movie.qualityClass === 'FULL HD' ? '1080p FHD' : (movie.qualityClass === 'HD' ? '720p HD' : '480p SD'));
        }
        qOptions = [{ key: 'direct', label: `Direct Stream (${honestRes})`, badge: honestRes }];
      } else if (sStateNow === 'TORRENT_SOURCE_AVAILABLE' || !!movie.torrentUri) {
        qOptions = [{ key: 'auto', label: 'Auto (Swarm Native)', badge: movie.qualityHonestBadge || 'Torrent HD' }];
      } else if (sStateNow === 'TRAILER_ONLY' || !!movie.trailerUrl) {
        qOptions = [{ key: 'trailer', label: 'Official Trailer', badge: 'Trailer' }];
      }

      qualityContainer.innerHTML = qOptions.map((opt, idx) => {
        const isSelected = (idx === 0);
        return `
          <button type="button" 
                  class="movie-quality-pill ${isSelected ? 'active' : ''}" 
                  onclick="selectMovieQualityOption('${opt.key}', '${opt.label}', this)">
            <span>${opt.label}</span>
            <span class="movie-quality-badge-tag">${opt.badge}</span>
            ${isSelected ? '<span class="check-icon">✓</span>' : ''}
          </button>
        `;
      }).join('');

      if (qualityBadge) {
        qualityBadge.textContent = qOptions[0] ? qOptions[0].label : 'Auto (Adaptive)';
      }
    }
  }

  // Web-Series Episodes Section
  const episodesSec = document.getElementById('seriesEpisodesSection');
  const episodesBadge = document.getElementById('seriesTotalEpisodesBadge');
  const episodesList = document.getElementById('seriesEpisodesList');
  const hasSeasonsData = movie.seasons && Array.isArray(movie.seasons) && movie.seasons.length > 0;
  const hasEpisodes = movie.episodes && movie.episodes.length > 0;

  if (movie.mediaType === 'series' && (hasSeasonsData || hasEpisodes)) {
    if (episodesSec) episodesSec.style.display = 'block';
    if (episodesBadge) episodesBadge.textContent = movie.durationFormatted || (movie.episodes ? movie.episodes.length + ' Episodes' : '');

    if (episodesList) {
      if (hasSeasonsData) {
        movie.seasons.sort((a, b) => (parseInt(a.seasonNumber, 10) || 0) - (parseInt(b.seasonNumber, 10) || 0));
        const seasonOptions = movie.seasons.map(s =>
          `<option value="${s.seasonNumber}">Season ${s.seasonNumber}${s.title ? ' — ' + s.title : ''}</option>`
        ).join('');

        const seasonSelector = `
          <div style="display: flex; align-items: center; gap: 10px; margin-bottom: 12px; padding: 0 4px;">
            <label style="font-size: 13px; font-weight: 700; color: #e2e8f0; white-space: nowrap;">Season:</label>
            <select id="seasonSelector" onchange="renderSeasonEpisodes('${movie.id}', this.value)"
              style="flex: 1; padding: 8px 12px; border-radius: 8px; border: 1px solid rgba(255,255,255,0.15); background: rgba(255,255,255,0.08); color: #f1f5f9; font-size: 13px; font-weight: 600; appearance: auto;">
              ${seasonOptions}
            </select>
          </div>
        `;
        const firstSeason = movie.seasons[0];
        const sortedFirstEps = [...(firstSeason.episodes || [])].sort((a, b) => (parseInt(a.episodeNumber, 10) || 0) - (parseInt(b.episodeNumber, 10) || 0));
        const firstSeasonEps = sortedFirstEps.map(ep => renderEpisodeItemMarkup(movie, ep)).join('');
        episodesList.innerHTML = seasonSelector + `<div id="seasonEpisodesContainer">${firstSeasonEps}</div>`;
      } else {
        const sortedFlatEps = [...(movie.episodes || [])].sort((a, b) => (parseInt(a.episodeNumber, 10) || 0) - (parseInt(b.episodeNumber, 10) || 0));
        episodesList.innerHTML = sortedFlatEps.map(ep => renderEpisodeItemMarkup(movie, ep)).join('');
      }
    }
  } else {
    if (episodesSec) episodesSec.style.display = 'none';
  }

  // Handle Download & Magnet action buttons
  const btnDownload = document.getElementById('btnMovieDownload');
  if (btnDownload) {
    const isDownloadable = !!movie.torrentUri || (!!movie.streamUrl && !movie.streamUrl.includes('.m3u8'));
    btnDownload.style.display = isDownloadable ? 'inline-flex' : 'none';
  }
  const btnMagnetCopy = document.getElementById('btnMovieMagnetCopy');
  if (btnMagnetCopy) {
    btnMagnetCopy.style.display = movie.torrentUri ? 'inline-flex' : 'none';
  }

  // Update watchlist button state
  updateWatchlistBtnState(movie.id);
}

window.renderSeasonEpisodes = function(movieId, seasonNumber) {
  const movie = CatalogProvider.getById(movieId);
  if (!movie || !movie.seasons) return;
  const season = movie.seasons.find(s => String(s.seasonNumber) === String(seasonNumber));
  if (!season) return;
  const selector = document.getElementById('seasonSelector');
  if (selector && selector.value !== String(seasonNumber)) {
    selector.value = String(seasonNumber);
  }
  const container = document.getElementById('seasonEpisodesContainer');
  if (!container) return;
  const sortedEps = [...(season.episodes || [])].sort((a, b) => (parseInt(a.episodeNumber, 10) || 0) - (parseInt(b.episodeNumber, 10) || 0));
  container.innerHTML = sortedEps.map(ep => renderEpisodeItemMarkup(movie, ep)).join('');
};

let _movieModalCloseTimer = null;

window.closeMovieDetails = function() {
  const modal = document.getElementById('movieDetailsModal');
  if (!modal || (!modal.classList.contains('active') && modal.style.display === 'none')) return;

  if (_movieModalPhase2Timer) {
    clearTimeout(_movieModalPhase2Timer);
    _movieModalPhase2Timer = null;
  }
  if (_movieModalCloseTimer) clearTimeout(_movieModalCloseTimer);
  modal.classList.remove('active');
  modal.classList.add('is-closing');
  document.body.classList.remove('modal-open-locked');
  document.documentElement.classList.remove('modal-open-locked');

  _movieModalCloseTimer = setTimeout(() => {
    modal.classList.remove('is-closing');
    _movieModalCloseTimer = null;
  }, 190);
};


function updateWatchlistBtnState(movieId) {
  const btn = document.getElementById('btnMovieWatchlist');
  const txt = document.getElementById('movieWatchlistText');
  if (!btn) return;
  try {
    const list = JSON.parse(localStorage.getItem('t2l_vod_watchlist') || '[]');
    const inList = list.includes(movieId);
    if (inList) {
      btn.classList.add('active');
      if (txt) txt.textContent = 'In My List';
    } else {
      btn.classList.remove('active');
      if (txt) txt.textContent = 'Add to List';
    }
  } catch (e) {}
}

window.toggleMovieWatchlist = function() {
  if (!currentSelectedMovie) return;
  const id = currentSelectedMovie.id;
  try {
    let list = JSON.parse(localStorage.getItem('t2l_vod_watchlist') || '[]');
    const idx = list.indexOf(id);
    if (idx >= 0) {
      list.splice(idx, 1);
      showToast('Removed from Watchlist');
    } else {
      list.push(id);
      showToast('Added to Watchlist ❤️');
    }
    localStorage.setItem('t2l_vod_watchlist', JSON.stringify(list));
    updateWatchlistBtnState(id);
  } catch (e) {}
};

window.copyMovieMagnet = function() {
  if (!currentSelectedMovie || !currentSelectedMovie.torrentUri) return;
  try {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(currentSelectedMovie.torrentUri);
      showToast('Magnet URI copied to clipboard 📋');
    } else {
      showToast('Magnet URI ready');
    }
  } catch (e) {
    showToast('Magnet URI ready');
  }
};

window.handleWatchTrailerClick = function() {
  if (!currentSelectedMovie || !currentSelectedMovie.trailerUrl) {
    showToast('Trailer is currently unavailable');
    return;
  }
  startMovieStream(currentSelectedMovie.id, currentSelectedMovie.trailerUrl, currentSelectedMovie.title + ' (Official Trailer)', true);
};

window.handleStreamMovieClick = function() {
  if (!currentSelectedMovie) return;
  const sState = currentSelectedMovie.sourceState || (currentSelectedMovie.streamUrl ? 'DIRECT_STREAM_AVAILABLE' : (currentSelectedMovie.trailerUrl ? 'TRAILER_ONLY' : (currentSelectedMovie.torrentUri ? 'TORRENT_SOURCE_AVAILABLE' : 'NO_AUTHORIZED_SOURCE')));

  if (sState === 'TRAILER_ONLY' || (!currentSelectedMovie.streamUrl && !currentSelectedMovie.torrentUri && currentSelectedMovie.trailerUrl)) {
    handleWatchTrailerClick();
    return;
  }

  if (sState === 'NO_AUTHORIZED_SOURCE' && !currentSelectedMovie.streamUrl && !currentSelectedMovie.torrentUri) {
    const title = currentSelectedMovie.title;
    if (currentSelectedMovie.trailerUrl) {
      handleWatchTrailerClick();
      return;
    }
    showToast('Streaming source will be available in the next catalog update for ' + title);
    return;
  }

  if (currentSelectedMovie.mediaType === 'series') {
    try {
      const resumeRaw = localStorage.getItem('t2l_resume_' + currentSelectedMovie.id);
      if (resumeRaw) {
        const r = JSON.parse(resumeRaw);
        if (r && r.episodeId) {
          let resumeEp = null;
          if (currentSelectedMovie.seasons) {
            for (const s of currentSelectedMovie.seasons) {
              if (s.episodes) {
                resumeEp = s.episodes.find(e => String(e.id) === String(r.episodeId));
                if (resumeEp) break;
              }
            }
          }
          if (!resumeEp && currentSelectedMovie.episodes) {
            resumeEp = currentSelectedMovie.episodes.find(e => String(e.id) === String(r.episodeId));
          }
          if (resumeEp && (resumeEp.streamUrl || (resumeEp.sourceState === 'TORRENT_SOURCE_AVAILABLE' && !!currentSelectedMovie.torrentUri))) {
            playSeriesEpisode(currentSelectedMovie.id, resumeEp.id);
            return;
          }
        }
      }
    } catch (e) {}
    // Find first playable episode, or fallback to first episode
    let targetEp = null;
    if (currentSelectedMovie.seasons && Array.isArray(currentSelectedMovie.seasons)) {
      for (const s of currentSelectedMovie.seasons) {
        if (s.episodes) {
          targetEp = s.episodes.find(e => !!e.streamUrl || (e.sourceState === 'TORRENT_SOURCE_AVAILABLE' && !!currentSelectedMovie.torrentUri));
          if (targetEp) break;
        }
      }
    }
    if (!targetEp && currentSelectedMovie.episodes) {
      targetEp = currentSelectedMovie.episodes.find(e => !!e.streamUrl || (e.sourceState === 'TORRENT_SOURCE_AVAILABLE' && !!currentSelectedMovie.torrentUri));
    }
    if (!targetEp) {
      targetEp = (currentSelectedMovie.seasons && currentSelectedMovie.seasons[0] && currentSelectedMovie.seasons[0].episodes && currentSelectedMovie.seasons[0].episodes[0]) ||
                 (currentSelectedMovie.episodes && currentSelectedMovie.episodes[0]);
    }
    if (targetEp) {
      playSeriesEpisode(currentSelectedMovie.id, targetEp.id);
      return;
    }
  }
  startMovieStream(currentSelectedMovie.id);
};

let preparedStreamUrl = null;
let preparedStreamTitle = '';
let activePlaybackSession = null;

window.playSeriesEpisode = function(movieId, episodeId) {
  const movie = CatalogProvider.getById(movieId);
  if (!movie) return;

  // Search episode across seasons first, then flat list (STRICT matching)
  let ep = null;
  if (movie.seasons && Array.isArray(movie.seasons)) {
    for (const s of movie.seasons) {
      if (s.episodes) {
        ep = s.episodes.find(e => String(e.id) === String(episodeId));
        if (ep) break;
      }
    }
  }
  if (!ep && movie.episodes) {
    ep = movie.episodes.find(e => String(e.id) === String(episodeId));
  }

  // Strictly reject if episode was requested by ID but does not exist
  if (!ep) {
    showToast('Episode not found in catalog');
    return;
  }

  const isTorrentPlayable = (ep.sourceState === 'TORRENT_SOURCE_AVAILABLE' || (!ep.sourceState && ep.season === 1)) && !!movie.torrentUri;
  if (!ep.streamUrl && !isTorrentPlayable) {
    const fullEpTitle = `${movie.title} - ${ep.title}`;
    if (ep.sourceState === 'NO_AUTHORIZED_SOURCE' || movie.sourceState === 'NO_AUTHORIZED_SOURCE') {
      showToast('No authorized public stream available for: ' + fullEpTitle + '. Use Instant Streamer to load your source.');
      if (typeof openInstantStreamerForContent === 'function') {
        openInstantStreamerForContent(fullEpTitle);
      }
    } else {
      showToast('Episode streaming source will be available in the next catalog update: ' + fullEpTitle);
    }
    return;
  }

  // Strict Episode Identity Invariant: Verify requested episode matches resolved episode
  if (String(ep.id) !== String(episodeId)) {
    showToast('Episode resolution identity violation');
    return;
  }

  window.currentPlayingEpisodeId = ep.id;
  nextEpDismissedForStream = false;

  const btnNext = document.getElementById('btnPlayerNextEp');
  if (btnNext) btnNext.style.display = 'inline-flex';

  const selectedLang = window.selectedMovieAudioLang || localStorage.getItem('t2l_preferred_movie_audio_lang') || movie.defaultLanguage || 'Hindi';
  let targetStreamUrl = ep.streamUrl;
  if (selectedLang && ep.audioStreams && ep.audioStreams[selectedLang]) {
    targetStreamUrl = ep.audioStreams[selectedLang];
  } else if (selectedLang && movie.audioStreams && movie.audioStreams[selectedLang]) {
    targetStreamUrl = movie.audioStreams[selectedLang];
  }

  const epTitle = `${movie.title}: ${ep.title}`;
  startMovieStream(movieId, targetStreamUrl, epTitle, false, ep.id);
};

window.startMovieStream = function(movieId, overrideUrl, overrideTitle, isTrailer, episodeId) {
  const movie = typeof movieId === 'object' ? movieId : CatalogProvider.getById(movieId);
  if (!movie) {
    showToast('Error: Content not found');
    return;
  }

  const selectedLang = window.selectedMovieAudioLang || localStorage.getItem('t2l_preferred_movie_audio_lang') || movie.defaultLanguage || 'Hindi';
  if (!overrideUrl && !isTrailer) {
    if (movie.audioStreams && movie.audioStreams[selectedLang]) {
      overrideUrl = movie.audioStreams[selectedLang];
    }
  }

  // Strict Validation: If movie/series requested, require movie source or torrent
  if (!isTrailer && !movie.torrentUri && !movie.streamUrl && !overrideUrl) {
    showToast('No authorized stream is currently available for ' + movie.title);
    return;
  }

  // If trailer requested, require trailer URL
  if (isTrailer && !overrideUrl && !movie.trailerUrl) {
    showToast('Trailer is currently unavailable for ' + movie.title);
    return;
  }


  // Create immutable playback session
  const sessionId = 'ps_' + Date.now() + '_' + Math.random().toString(36).substring(2, 9);
  activePlaybackSession = {
    sessionId: sessionId,
    contentId: movie.id,
    contentType: isTrailer ? 'TRAILER' : (movie.contentType || (movie.mediaType === 'series' ? 'SERIES' : 'MOVIE')),
    title: movie.title,
    overrideTitle: overrideTitle,
    overrideUrl: overrideUrl,
    isTrailer: !!isTrailer,
    episodeId: episodeId || null,
    torrentUri: movie.torrentUri || null,
    requestedAt: Date.now()
  };

  currentSelectedMovie = movie;
  closeMovieDetails();

  const btnNext = document.getElementById('btnPlayerNextEp');
  if (btnNext && !episodeId) btnNext.style.display = 'none';
  if (!episodeId) window.currentPlayingEpisodeId = null;
  window.nextEpPromptShown = false;

  // Record into watch history only if actual movie/series
  if (!isTrailer) {
    try {
      let history = JSON.parse(localStorage.getItem('t2l_vod_history') || '[]');
      history = history.filter(id => id !== movie.id);
      history.unshift(movie.id);
      if (history.length > 12) history.pop();
      localStorage.setItem('t2l_vod_history', JSON.stringify(history));
    } catch (e) {}
  }

  const streamDisplayTitle = overrideTitle || (isTrailer ? movie.title + ' (Official Trailer)' : movie.title);
  preparedStreamTitle = streamDisplayTitle;

  let streamUrl = overrideUrl || (isTrailer ? movie.trailerUrl : movie.streamUrl);
  preparedStreamUrl = streamUrl;

  const isDirectOrTrailer = isTrailer || !!movie.streamUrl || !!overrideUrl;
  if (isDirectOrTrailer) {
    // Instant fast-start: zero modal flicker, launch playback immediately
    forceLaunchPreparedStream(sessionId);
    return;
  }

  // Open Stream Prep Modal ONLY for P2P/torrent swarms
  const prepModal = document.getElementById('streamPrepModal');
  const titleEl = document.getElementById('streamPrepMovieTitle');
  const barEl = document.getElementById('streamPrepProgressBar');
  const statusEl = document.getElementById('streamPrepStatusText');
  const pctEl = document.getElementById('streamPrepPctText');
  const startBtn = document.getElementById('btnStreamPrepStart');

  if (titleEl) titleEl.textContent = streamDisplayTitle + ' (' + (movie.resolution ? movie.resolution.split(' ')[0] : '1080p') + ')';
  if (barEl) barEl.style.width = '20%';
  if (statusEl) statusEl.textContent = 'Connecting to Distributed Torrent Swarm...';
  if (pctEl) pctEl.textContent = '20%';
  if (startBtn) startBtn.disabled = true;

  setPrepStage(1, 'done');
  setPrepStage(2, 'active');
  setPrepStage(3, 'pending');
  setPrepStage(4, 'pending');

  if (prepModal) {
    prepModal.classList.add('active');
    prepModal.style.display = 'flex';
  }

  let rawRes = null;
  if (movie.torrentUri && window.AndroidMedia && window.AndroidMedia.startTorrentStream) {
    try {
      rawRes = window.AndroidMedia.startTorrentStream(movie.torrentUri);
    } catch (e) {
      console.error('startTorrentStream error:', e);
    }
  }

  let localPort = 8080;
  if (window.AndroidMedia && window.AndroidMedia.getLocalServerPort) {
    try { localPort = window.AndroidMedia.getLocalServerPort(); } catch (e) {}
  }

  if (!streamUrl) {
    streamUrl = 'http://127.0.0.1:' + localPort + '/torrent/stream';
    if (rawRes) {
      try {
        const parsed = JSON.parse(rawRes);
        if (parsed.streamUrl) streamUrl = parsed.streamUrl;
      } catch (e) {}
    }
  }
  preparedStreamUrl = streamUrl;

  // Poll progress with session guard to eliminate race conditions
  let ticks = 0;
  if (streamPrepInterval) clearInterval(streamPrepInterval);
  const currentSessionId = sessionId;

  streamPrepInterval = setInterval(() => {
    // Guard against stale callback from previous request
    if (!activePlaybackSession || activePlaybackSession.sessionId !== currentSessionId) {
      clearInterval(streamPrepInterval);
      return;
    }

    ticks++;
    let peers = 0;
    let verified = 0;

    if (window.AndroidMedia && window.AndroidMedia.getTorrentStatus) {
      try {
        const s = JSON.parse(window.AndroidMedia.getTorrentStatus());
        peers = s.connectedPeers || 0;
        verified = s.verifiedPieces || 0;
      } catch (e) {}
    }

    const peerCounter = document.getElementById('prepPeerCount');
    if (peerCounter) peerCounter.textContent = peers;
      // Torrent streaming: check peer discovery and pieces
      if (verified > 0 || peers > 0) {
        setPrepStage(2, 'done');
        setPrepStage(3, 'done');
        setPrepStage(4, 'done');
        if (barEl) barEl.style.width = '100%';
        if (pctEl) pctEl.textContent = '100%';
        if (statusEl) statusEl.textContent = `Swarm connected (${peers} peers)! Launching stream...`;
        if (startBtn) startBtn.disabled = false;
        clearInterval(streamPrepInterval);
        streamPrepInterval = null;
        setTimeout(() => {
          if (activePlaybackSession && activePlaybackSession.sessionId === currentSessionId) {
            forceLaunchPreparedStream(currentSessionId);
          }
        }, 400);
      } else if (ticks < 10) {
        setPrepStage(2, 'active');
        if (statusEl) statusEl.textContent = `Connecting to distributed swarm... searching for peers (${ticks}s)`;
        if (barEl) barEl.style.width = Math.min(20 + ticks * 5, 75) + '%';
        if (pctEl) pctEl.textContent = Math.min(20 + ticks * 5, 75) + '%';
      } else {
        // Swarm unreachable or 0 peers after 5 seconds
        clearInterval(streamPrepInterval);
        streamPrepInterval = null;
        setPrepStage(2, 'pending');
        if (statusEl) statusEl.textContent = 'Torrent Swarm Offline: 0 reachable peers.';
        if (barEl) barEl.style.width = '30%';
        if (pctEl) pctEl.textContent = '30%';
        showToast('Torrent swarm offline: No active seeders found.');
      }
  }, 500);
};

function setPrepStage(stageNum, state) {
  const el = document.getElementById('prepStage' + stageNum);
  if (!el) return;
  el.className = 'prep-stage-item stage-' + state;
  const icon = el.querySelector('.prep-stage-icon');
  if (icon) {
    if (state === 'done') icon.textContent = '✓';
    else if (state === 'active') icon.textContent = '⏳';
    else icon.textContent = '○';
  }
}

window.cancelStreamPreparation = function() {
  if (streamPrepInterval) {
    clearInterval(streamPrepInterval);
    streamPrepInterval = null;
  }
  const modal = document.getElementById('streamPrepModal');
  if (modal) {
    modal.classList.remove('active');
    modal.style.display = 'none';
  }
};

window.forceLaunchPreparedStream = function(expectedSessionId) {
  cancelStreamPreparation();

  // Session race-condition validation
  if (expectedSessionId && activePlaybackSession && activePlaybackSession.sessionId !== expectedSessionId) {
    console.warn('Blocked stale stream launch for session:', expectedSessionId);
    return;
  }

  const movie = currentSelectedMovie;
  if (!movie) return;

  const session = activePlaybackSession;
  const isTrailer = session ? session.isTrailer : false;

  let primaryUrl = null;
  const backups = [];

  if (isTrailer) {
    // Explicit Trailer playback requested
    primaryUrl = (session && session.overrideUrl) || movie.trailerUrl;
  } else {
    // MOVIE or SERIES playback requested — NEVER substitute trailer!
    if (movie.isCustomMagnet) {
      primaryUrl = preparedStreamUrl || movie.streamUrl;
    } else if (session && session.overrideUrl) {
      primaryUrl = session.overrideUrl;
    } else if (movie.streamUrl) {
      primaryUrl = movie.streamUrl;
    } else if (preparedStreamUrl) {
      // Ensure preparedStreamUrl is not accidentally a trailer
      if (movie.trailerUrl && preparedStreamUrl === movie.trailerUrl) {
        primaryUrl = null;
      } else {
        primaryUrl = preparedStreamUrl;
      }
    }
  }

  if (movie.backupUrls && Array.isArray(movie.backupUrls)) {
    movie.backupUrls.forEach(u => {
      if (u && !backups.includes(u) && u !== primaryUrl && (!movie.trailerUrl || u !== movie.trailerUrl)) {
        backups.push(u);
      }
    });
  }

  if (session && session.episodeId) {
    let epObj = null;
    if (movie.seasons && Array.isArray(movie.seasons)) {
      for (const s of movie.seasons) {
        if (s.episodes) {
          epObj = s.episodes.find(e => String(e.id) === String(session.episodeId));
          if (epObj) break;
        }
      }
    }
    if (!epObj && movie.episodes) {
      epObj = movie.episodes.find(e => String(e.id) === String(session.episodeId));
    }
    if (epObj && epObj.backupUrls && Array.isArray(epObj.backupUrls)) {
      epObj.backupUrls.forEach(u => {
        if (u && !backups.includes(u) && u !== primaryUrl) {
          backups.push(u);
        }
      });
    }
  }

  // Pre-playback validation: Never play if primaryUrl is missing or invalid
  if (!primaryUrl) {
    showToast('No authorized movie source is currently available.');
    return;
  }

  const launchTitle = (session && session.overrideTitle) || preparedStreamTitle || (isTrailer ? movie.title + ' (Official Trailer)' : movie.title);

  startTorrentPlayback(
    primaryUrl,
    launchTitle,
    movie.id,
    backups.filter(u => u !== primaryUrl),
    movie
  );
};

// ==========================================================
// OFFLINE DOWNLOADS SUBSYSTEM
// ==========================================================
window.handleDownloadMovieClick = function() {
  if (!currentSelectedMovie) return;
  startMovieDownload(currentSelectedMovie);
};

window.startMovieDownload = function(movie) {
  if (!movie) return;

  const safeTitle = (movie.title || 'video').replace(/[^a-zA-Z0-9_-]/g, '_');
  const container = (movie.container || 'mp4').toLowerCase();
  const filename = `${safeTitle}.${container}`;

  // Route 1: Torrent download (magnet URI available)
  if (movie.torrentUri) {
    closeMovieDetails();
    if (window.AndroidMedia && window.AndroidMedia.startTorrentDownload) {
      try {
        window.AndroidMedia.startTorrentDownload(movie.torrentUri, movie.title, filename);
        showToast('⬇️ Torrent Download Queued: ' + movie.title);
      } catch (e) {
        showToast('Download started');
      }
    } else {
      showToast('Download manager ready');
    }
    openDownloadsManagerModal();
    return;
  }

  // Route 2: HTTP download (direct stream URL available as progressive MP4)
  if (movie.streamUrl && !movie.streamUrl.includes('.m3u8')) {
    closeMovieDetails();
    if (window.AndroidMedia && window.AndroidMedia.startHttpDownload) {
      try {
        window.AndroidMedia.startHttpDownload(movie.streamUrl, movie.title, filename);
        showToast('⬇️ Download Started: ' + movie.title);
      } catch (e) {
        showToast('Download started');
      }
    } else {
      // Fallback: try opening URL in browser for download
      try {
        window.open(movie.streamUrl, '_blank');
        showToast('Opening download in browser...');
      } catch (e) {
        showToast('Download unavailable');
      }
    }
    openDownloadsManagerModal();
    return;
  }

  // Route 3: HLS stream — cannot be downloaded directly
  if (movie.streamUrl && movie.streamUrl.includes('.m3u8')) {
    showToast('⚠️ Adaptive streams cannot be downloaded offline');
    return;
  }

  // Route 4: Trailer-only or unavailable — no download possible
  if (movie.sourceState === 'TRAILER_ONLY' || movie.trailerUrl) {
    showToast('⚠️ Only the trailer is available — full movie download is not available');
    return;
  }

  showToast('⚠️ Download is not available for this title');
};

window.openDownloadsManagerModal = function() {
  const modal = document.getElementById('downloadsManagerModal');
  if (modal) {
    modal.classList.add('active');
    modal.style.display = 'flex';
  }
  renderDownloadsManager();
  if (downloadsManagerInterval) clearInterval(downloadsManagerInterval);
  downloadsManagerInterval = setInterval(renderDownloadsManager, 1500);
};

window.closeDownloadsManagerModal = function() {
  if (downloadsManagerInterval) {
    clearInterval(downloadsManagerInterval);
    downloadsManagerInterval = null;
  }
  const modal = document.getElementById('downloadsManagerModal');
  if (modal) {
    modal.classList.remove('active');
    modal.style.display = 'none';
  }
};

window.switchDownloadsTab = function(tab) {
  activeDownloadsTab = tab;
  const tabActive = document.getElementById('tabDownloadsActive');
  const tabCompleted = document.getElementById('tabDownloadsCompleted');
  const activeList = document.getElementById('downloadsActiveList');
  const completedList = document.getElementById('downloadsCompletedList');

  if (tab === 'active') {
    if (tabActive) tabActive.classList.add('active');
    if (tabCompleted) tabCompleted.classList.remove('active');
    if (activeList) activeList.style.display = 'flex';
    if (completedList) completedList.style.display = 'none';
  } else {
    if (tabActive) tabActive.classList.remove('active');
    if (tabCompleted) tabCompleted.classList.add('active');
    if (activeList) activeList.style.display = 'none';
    if (completedList) completedList.style.display = 'flex';
  }
};

window.renderDownloadsManager = function() {
  let tasks = [];
  if (window.AndroidMedia && window.AndroidMedia.getDownloadTasks) {
    try {
      const raw = window.AndroidMedia.getDownloadTasks();
      tasks = JSON.parse(raw);
    } catch (e) {}
  }

  const activeTasks = tasks.filter(t => t.status === 'DOWNLOADING' || t.status === 'PAUSED' || t.status === 'QUEUED');
  const completedTasks = tasks.filter(t => t.status === 'COMPLETED');

  const countActive = document.getElementById('countDownloadsActive');
  const countCompleted = document.getElementById('countDownloadsCompleted');
  if (countActive) countActive.textContent = activeTasks.length;
  if (countCompleted) countCompleted.textContent = completedTasks.length;

  // Render Active List
  const activeList = document.getElementById('downloadsActiveList');
  if (activeList) {
    if (activeTasks.length === 0) {
      activeList.innerHTML = `
        <div style="padding: 28px 16px; text-align: center; color: #94a3b8;">
          <p style="font-size: 14px; margin-bottom: 4px;">No active downloads</p>
          <p style="font-size: 11px; color: #64748b;">Browse Movies to download authorized cinema for offline playback</p>
        </div>
      `;
    } else {
      activeList.innerHTML = activeTasks.map(t => {
        const pct = Math.min(100, Math.round((t.progress || 0) * 100));
        const speed = t.speedBytesPerSec > 1024 * 1024 ? (t.speedBytesPerSec / (1024 * 1024)).toFixed(1) + ' MB/s' : Math.round((t.speedBytesPerSec || 0) / 1024) + ' KB/s';
        const dlMb = ((t.downloadedBytes || 0) / (1024 * 1024)).toFixed(1);
        const totalMb = ((t.totalBytes || 0) / (1024 * 1024)).toFixed(1);

        return `
          <div class="download-task-item">
            <div class="download-task-header">
              <span class="download-task-title">${t.title}</span>
              <button class="task-action-btn task-btn-cancel" onclick="cancelTorrentDownloadTask('${t.taskId}')">Cancel</button>
            </div>
            <div class="telemetry-progress-bar">
              <div class="telemetry-progress-fill" style="width: ${pct}%;"></div>
            </div>
            <div class="download-task-meta">
              <span>${pct}% • ↓ ${speed}</span>
              <span>${dlMb} MB / ${totalMb} MB</span>
            </div>
          </div>
        `;
      }).join('');
    }
  }

  // Render Completed List
  const completedList = document.getElementById('downloadsCompletedList');
  if (completedList) {
    if (completedTasks.length === 0) {
      completedList.innerHTML = `
        <div style="padding: 28px 16px; text-align: center; color: #94a3b8;">
          <p style="font-size: 14px; margin-bottom: 4px;">No completed downloads yet</p>
          <p style="font-size: 11px; color: #64748b;">Completed files are saved directly into your device's Local Media library</p>
        </div>
      `;
    } else {
      completedList.innerHTML = completedTasks.map(t => {
        const totalMb = ((t.totalBytes || 0) / (1024 * 1024)).toFixed(1);
        return `
          <div class="download-task-item">
            <div class="download-task-header">
              <span class="download-task-title">${t.title}</span>
              <div style="display: flex; gap: 6px;">
                <button class="task-action-btn task-btn-play" onclick="playDownloadedFile('${t.localFilePath}', '${t.title}')">▶ Play</button>
                <button class="task-action-btn task-btn-cancel" onclick="deleteDownloadedTaskFile('${t.taskId}')" title="Delete"><svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor"><path d="M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z"/></svg></button>
              </div>
            </div>
            <div class="download-task-meta">
              <span style="color: #4ade80;">✓ Ready to watch offline</span>
              <span>${totalMb} MB</span>
            </div>
          </div>
        `;
      }).join('');
    }
  }

  // Storage info
  const storageText = document.getElementById('downloadsStorageText');
  if (storageText) {
    const totalCompletedBytes = completedTasks.reduce((acc, t) => acc + (t.totalBytes || 0), 0);
    const usedMb = (totalCompletedBytes / (1024 * 1024)).toFixed(1);
    storageText.textContent = `${usedMb} MB Used • Free Space Available`;
  }
};

